  if(view.panel==='briefs')return tabs+(!hosted()?'<p class="field-help">Saved on this computer. No Angbao account is required.</p>':'')+researchBriefsMarkup(view);
  if(view.panel==='import')return tabs+researchImportMarkup(view);
  if(!hosted())return tabs+'<p>Your personal agent can save final research and citations here without an account.</p><p class="field-help">Live search requires enabled account access. Saving briefs does not call Elfa or a model.</p>'+button('Saved briefs','research-briefs','secondary')+button('New brief','research-import','secondary');
