function resetResearchAuthor(view){view.methodWorkId=null;view.methodRunDigest=null;view.authorMode='guided';view.authorDraft=createResearchDraft();view.authorRevision=(view.authorRevision||0)+1;view.briefPreview=null;view.importText='';view.importDirty=false;view.briefError=null;}
