function captureResearchAuthorForm(data,view){
  if(!data?.get)return;
  if(view.authorMode==='json'){const raw=data.get('briefJson');if(raw!==null&&raw!==undefined&&String(raw)!==view.importText){view.importText=String(raw);invalidateResearchPreview(view);}return;}
  if(data.get('briefEditor')!=='guided')return;
  for(const key of ['question','answer','authorship'])view.authorDraft[key]=String(data.get(`brief-${key}`)||'');
  for(const [index,item] of view.authorDraft.evidence.entries())for(const key of ['title','url','excerpt','publishedAt','observedAt']){const value=String(data.get(`source-${index}-${key}`)||'');item[key]=['publishedAt','observedAt'].includes(key)&&value===''?null:value;}
  for(const [index,item] of view.authorDraft.claims.entries()){item.text=String(data.get(`claim-${index}-text`)||'');item.stance=String(data.get(`claim-${index}-stance`)||'');item.evidenceIds=data.getAll(`claim-${index}-evidenceIds`);}
  for(const [index,item] of view.authorDraft.inferences.entries()){item.text=String(data.get(`inference-${index}-text`)||'');item.claimIds=data.getAll(`inference-${index}-claimIds`);}
  view.authorDraft.gaps=view.authorDraft.gaps.map((_,index)=>String(data.get(`gap-${index}`)||''));invalidateResearchPreview(view);
}
async function previewResearchBrief(data){
  const view=researchView;if(!researchAuthorReady(view))return;
  captureResearchAuthorForm(data,view);view.importDirty=true;view.briefError=null;
  try{const raw=view.authorMode==='json'?briefImportPayload(view.importText):view.authorDraft,payload=briefImportPayload(JSON.stringify(researchDraftPayload(raw)));const signature=authorSignature(view),revision=view.authorRevision;if(view.methodWorkId){view.loading=true;updateResearchModal();const checked=await requestResearchWorkPreview(view.methodWorkId,payload,view,signature);if(!checked||researchView!==view||signature!==authorSignature(view)||revision!==view.authorRevision)return;}view.briefPreview={payload,signature,revision,methodWorkId:view.methodWorkId||null};}
  catch(error){view.briefPreview=null;view.briefError=error.message;}
  finally{view.loading=false;if(researchView===view)updateResearchModal();}
}
function editResearchBrief(){if(!researchAuthorReady())return;researchView.briefPreview=null;updateResearchModal();}
function researchAuthorInput(label,name,value,attributes,section,index,key){return field(label,name,value,`${attributes} data-brief-section="${section}" ${index===null?'':`data-brief-index="${index}"`} data-brief-key="${key}"`);}
function researchAuthorText(label,name,value,max,section,index,key,rows=3){return `<div class="field"><label for="${esc(name)}">${label}</label><textarea id="${esc(name)}" name="${esc(name)}" rows="${rows}" maxlength="${max}" required data-brief-section="${section}" ${index===null?'':`data-brief-index="${index}"`} data-brief-key="${key}">${esc(value)}</textarea></div>`;}
function researchAuthorRefs(items,selected,section,index,ref,label){return `<fieldset class="brief-reference-choices"><legend>${label}</legend>${items.length?items.map(item=>`<label><input id="brief-${section}-${index}-${ref}-${esc(item.id)}" type="checkbox" name="${section==='claims'?'claim':'inference'}-${index}-${ref}" value="${esc(item.id)}" data-brief-section="${section}" data-brief-index="${index}" data-brief-ref="${ref}" ${selected.includes(item.id)?'checked':''}><span>${esc(item.title||item.text||'Untitled item')}</span></label>`).join(''):'<p class="field-help">'+(section==='claims'?'Add a source above, then select it here.':'Add a claim above to link it here.')+'</p>'}</fieldset>`;}
function researchGuidedMarkup(view){
  const draft=view.authorDraft,remove=(section,index)=>button('Remove','research-remove-item','ghost small',`data-section="${section}" data-index="${index}"`),add=(label,section,count,max)=>button(label,'research-add-item','secondary small',`data-section="${section}" ${count>=max?'disabled':''}`);
  return `<input type="hidden" name="briefEditor" value="guided">${researchAuthorText('Question · up to 500 characters','brief-question',draft.question,500,'root',null,'question',2)}${researchAuthorText('Answer · up to 3,000 characters','brief-answer',draft.answer,3000,'root',null,'answer',6)}<div class="field"><label for="brief-authorship">Origin</label><select id="brief-authorship" name="brief-authorship" data-brief-section="root" data-brief-key="authorship"><option value="agent-authored" ${draft.authorship==='agent-authored'?'selected':''}>Agent-written</option><option value="imported" ${draft.authorship==='imported'?'selected':''}>Imported</option></select></div><section class="brief-author-section"><div class="section-head"><h3>Sources</h3><span class="field-help">${draft.evidence.length} of 12</span></div><p class="field-help">Public HTTPS links only. Source titles are used to link claims below.</p>${draft.evidence.map((item,index)=>`<article class="brief-author-row"><div class="section-head"><h4>Source ${index+1}</h4>${remove('evidence',index)}</div>${researchAuthorInput('Title · up to 160 characters',`source-${index}-title`,item.title,'required maxlength="160"','evidence',index,'title')}${researchAuthorInput('Public link',`source-${index}-url`,item.url,'type="url" required maxlength="2000" placeholder="https://…"','evidence',index,'url')}${researchAuthorInput('Excerpt (optional) · up to 600 characters',`source-${index}-excerpt`,item.excerpt||'','maxlength="600"','evidence',index,'excerpt')}<details class="record-details"><summary>Source dates (optional)</summary><p class="field-help">Leave unknown dates blank. For a known UTC time use 2026-10-24T00:00:00.000Z.</p>${researchAuthorInput('Published at',`source-${index}-publishedAt`,item.publishedAt||'','maxlength="24" placeholder="Unknown"','evidence',index,'publishedAt')}${researchAuthorInput('Observed at',`source-${index}-observedAt`,item.observedAt||'','maxlength="24" placeholder="Unknown"','evidence',index,'observedAt')}</details></article>`).join('')}${add('Add source','evidence',draft.evidence.length,12)}</section><section class="brief-author-section"><div class="section-head"><h3>Claims</h3><span class="field-help">${draft.claims.length} of 12</span></div>${draft.claims.map((item,index)=>`<article class="brief-author-row"><div class="section-head"><h4>Claim ${index+1}</h4>${remove('claims',index)}</div>${researchAuthorText('Claim · up to 700 characters',`claim-${index}-text`,item.text,700,'claims',index,'text')}<div class="field"><label for="claim-${index}-stance">Evidence</label><select id="claim-${index}-stance" name="claim-${index}-stance" data-brief-section="claims" data-brief-index="${index}" data-brief-key="stance"><option value="supporting" ${item.stance==='supporting'?'selected':''}>Supporting</option><option value="contradicting" ${item.stance==='contradicting'?'selected':''}>Contradicting</option></select></div>${researchAuthorRefs(draft.evidence,item.evidenceIds,'claims',index,'evidenceIds','Select at least one source')}</article>`).join('')}${add('Add claim','claims',draft.claims.length,12)}</section><section class="brief-author-section"><div class="section-head"><h3>Inferences</h3><span class="field-help">${draft.inferences.length} of 8</span></div><p class="field-help">Your interpretation, kept separate from the source claims.</p>${draft.inferences.map((item,index)=>`<article class="brief-author-row"><div class="section-head"><h4>Inference ${index+1}</h4>${remove('inferences',index)}</div>${researchAuthorText('Inference · up to 700 characters',`inference-${index}-text`,item.text,700,'inferences',index,'text')}${researchAuthorRefs(draft.claims,item.claimIds,'inferences',index,'claimIds','Related claims (optional)')}</article>`).join('')}${add('Add inference','inferences',draft.inferences.length,8)}</section><section class="brief-author-section"><div class="section-head"><h3>Gaps</h3><span class="field-help">${draft.gaps.length} of 8</span></div>${draft.gaps.map((item,index)=>`<article class="brief-author-row"><div class="section-head"><h4>Gap ${index+1}</h4>${remove('gaps',index)}</div>${researchAuthorText('What is missing or uncertain? · up to 500 characters',`gap-${index}`,item,500,'gaps',index,'text')}</article>`).join('')}${add('Add gap','gaps',draft.gaps.length,8)}</section>`;
}
function researchPreviewMarkup(view){
  const brief=view.briefPreview.payload,sources=new Map(brief.evidence.map(item=>[item.id,item.title])),claims=new Map(brief.claims.map(item=>[item.id,item.text])),time=value=>value?researchTime(value):'Unknown';
  return `<article class="research-brief-preview"><div class="section-head"><h3>Preview brief</h3><span class="status">Unverified · preview</span></div><h4>${esc(brief.question)}</h4><p class="brief-answer">${esc(brief.answer)}</p><p class="field-help">${brief.authorship==='agent-authored'?'Agent-written':'Imported'}. Sources have not been independently checked.</p><section><h4>Sources</h4>${brief.evidence.length?`<ol class="brief-sources">${brief.evidence.map(item=>`<li><a class="quiet-link" href="${esc(briefCitation(item.url))}" target="_blank" rel="noopener noreferrer">${esc(item.title)} ↗</a>${item.excerpt?`<p>${esc(item.excerpt)}</p>`:''}<p class="field-help">Published: ${time(item.publishedAt)} · Observed: ${time(item.observedAt)}</p></li>`).join('')}</ol>`:'<p class="field-help">No sources supplied.</p>'}</section><section><h4>Claims</h4>${brief.claims.length?`<ul class="brief-claims">${brief.claims.map(item=>`<li><p><strong>${item.stance==='supporting'?'Supporting':'Contradicting'}:</strong> ${esc(item.text)}</p><span class="field-help">Sources: ${item.evidenceIds.map(id=>esc(sources.get(id))).join(', ')}</span></li>`).join('')}</ul>`:'<p class="field-help">None supplied.</p>'}</section><section><h4>Inferences</h4>${brief.inferences.length?`<ul class="brief-claims">${brief.inferences.map(item=>`<li>${esc(item.text)}${item.claimIds.length?`<span class="field-help">Related claims: ${item.claimIds.map(id=>esc(claims.get(id))).join('; ')}</span>`:''}</li>`).join('')}</ul>`:'<p class="field-help">None supplied.</p>'}</section><section><h4>Gaps</h4>${brief.gaps.length?`<ul class="brief-claims">${brief.gaps.map(item=>`<li>${esc(item)}</li>`).join('')}</ul>`:'<p class="field-help">No gaps listed. This does not confirm completeness.</p>'}</section><p class="field-help">Keeps the latest 20 saved versions. Saving does not contact a provider or model.</p>${brief.previousVersionId||brief.baselineId?`<details class="record-details"><summary>Version references</summary>${brief.previousVersionId?`<p>Previous version: <code>${esc(brief.previousVersionId)}</code></p>`:''}${brief.baselineId?`<p>Comparison version: <code>${esc(brief.baselineId)}</code></p>`:''}</details>`:''}<div class="actions">${button('Edit brief','research-edit-brief','secondary')}${button('Save brief','research-save-brief','primary',api?'':'disabled')}</div>${!api?'<p class="field-help">This is a browser preview. <a href="/agent-setup.html">Start Angbao on this device</a> to save without an account.</p>':''}</article>`;
}
function researchImportMarkup(view){
  if(!view.authorDraft)view.authorDraft=createResearchDraft();if(!view.authorMode)view.authorMode='guided';
  return `<section class="research-memory"><div class="section-head"><h2>New brief</h2><span class="status">${['/api/research/briefs','/api/research/methods/complete'].includes(pendingRequest?.url)&&syncIssue?.type==='unconfirmed'?'Save unconfirmed':view.importDirty?'Draft':'New'}</span></div><p class="field-help">Keep the final answer, sources and uncertainty. Do not include credentials or private reasoning.</p>${view.briefError?`<p class="inline-note" role="alert">${esc(view.briefError)}</p>`:''}${view.briefPreview?researchPreviewMarkup(view):`<form data-form="research-brief">${view.authorMode==='guided'?researchGuidedMarkup(view):`<label for="research-brief-json">Brief JSON</label><textarea id="research-brief-json" name="briefJson" class="code-block brief-import" rows="13" maxlength="20000" spellcheck="false" required>${esc(view.importText)}</textarea>`}<div class="actions"><button class="button primary" type="submit">Preview brief</button>${view.importDirty?button('Discard draft','research-discard-import','ghost small'):''}</div></form><details class="record-details"><summary>Advanced JSON</summary><p class="field-help">Use the same brief fields and references as your agent. Switching back to the form checks the JSON first.</p><div class="actions">${button(view.authorMode==='json'?'Use guided form':'Edit JSON',view.authorMode==='json'?'research-guided':'research-json','secondary small')}${button('Copy brief format','research-format','secondary small')}</div><p class="field-help">Up to 12 sources and claims, 8 inferences and gaps, and 12 KiB in total. Leave unknown source dates blank in the form or null in JSON.</p></details>`}<p class="field-help">Unsaved drafts stay in this session and are lost on reload.</p></section>`;
}

function switchResearchPanel(panel){
  if(!researchModalOpen||!researchView||!['evidence','briefs','import','work'].includes(panel))return;
  if(researchView.panel==='portfolio'&&researchView.portfolio?.dirty){researchView.portfolio.error='Save or discard the portfolio draft before switching views.';updateResearchModal();return;}
  cancelResearchRead();researchView.panel=panel;researchView.briefError=null;updateResearchModal();
  if(panel==='briefs'&&!researchView.briefsLoaded)void loadResearchBriefs();
  if(panel==='work')void loadResearchWork();
}
async function requestBriefRead(path,current){
  const owner=connection.userId;try{await verifyIdentity();}catch(error){if(!current())return null;if(error.status===401||error.code==='identity_changed')researchAuthFailure(error,owner);throw clientError('The workspace could not be checked. Reopen saved briefs to try again.');}if(!current())return null;
  let response;try{response=await workspaceFetch(path,{credentials:'same-origin',cache:'no-store',redirect:'error',signal:AbortSignal.timeout(12000)});}catch{throw clientError('Saved briefs could not be loaded. Refresh briefs to try again.');}
  if(!current())return null;
  if(response.status===401){researchAuthFailure(clientError('Sign in again before reading saved briefs.',{status:401}),owner);return null;}
  let data;try{data=await readAgentAccessJSON(response);}catch{throw clientError('The brief could not be confirmed. Refresh the saved briefs before continuing.');}if(!current())return null;
  if(hosted()&&data?.requestIdentity?.userId!==owner){if(response.status>=500&&!data?.requestIdentity)throw clientError('Research memory is unavailable.');researchAuthFailure(clientError('This brief belongs to a different account. Reload before continuing.',{status:401}),owner);return null;}
  if(!response.ok)throw clientError(data.error?.message||'Saved briefs are unavailable.');
  const etag=response.headers.get('ETag');if(!/^"(?:0|[1-9]\d*)"$/.test(etag||'')||!briefTruth(data.capabilityTruth))throw clientError('The brief could not be confirmed. Refresh the saved briefs before continuing.');
  return {data,etag};
}
async function loadResearchBriefs(id=null){
  const view=researchView;if(!researchModalOpen||!view||!api||view.ownerId!==connection.userId||view.loading||id!==null&&!agentGrantUUID.test(id))return;
  view.panel='briefs';view.loading=true;view.briefError=null;const serial=++researchSerial,current=()=>researchCurrent(view,serial);updateResearchModal();
  try{
    const result=await requestBriefRead(id?`/api/research/briefs/${id}`:'/api/research/briefs',current);if(!current()||!result)return;
    if(id){if(result.data.brief?.id!==id)throw clientError('A different brief version was returned. Refresh saved briefs before continuing.');view.selectedBrief=validBriefRecord(result.data.brief);}
    else{const {briefs,retention}=result.data;if(!Array.isArray(briefs)||briefs.length>20||retention?.maxVersions!==20||retention.completeHistory!==false||briefs.some(item=>!item||!agentGrantUUID.test(item.id)||!agentGrantUUID.test(item.seriesId)||!Number.isInteger(item.version)||item.version<1||typeof item.question!=='string'||item.question.length>500||typeof item.answerPreview!=='string'||item.answerPreview.length>240||!['agent-authored','imported'].includes(item.authorship)||item.verification!=='unverified'||!['manual-gui','personal-agent-token','headless-cli'].includes(item.source)||!Number.isFinite(Date.parse(item.createdAt))))throw clientError('The brief list could not be confirmed. Refresh briefs to try again.');view.briefs=briefs;view.briefsLoaded=true;view.selectedBrief=null;}
    view.briefsETag=result.etag;
  }catch(error){if(current())view.briefError=error.message;}
  finally{if(current()){view.loading=false;updateResearchModal();}}
}
function nextResearchVersion(id){
  if(researchView?.selectedBrief?.methodRunRef){void copyContinuation('research-method',researchView.selectedBrief.methodRunRef.workId);return;}
  const view=researchView,brief=view?.selectedBrief;if(!brief||brief.id!==id||view.importDirty){if(view?.importDirty){view.briefError='A brief has unsaved edits. Save or discard them before starting another version.';view.panel='import';updateResearchModal();}return;}
  const value=Object.fromEntries(['question','answer','authorship','claims','inferences','gaps'].map(key=>[key,brief[key]]));value.evidence=brief.evidence.map(({provenance,...item})=>item);value.previousVersionId=brief.id;if(brief.baseline?.reference?.id)value.baselineId=brief.baseline.reference.id;
  view.authorDraft=createResearchDraft(value);view.authorMode='guided';invalidateResearchPreview(view);view.panel='import';view.briefError=null;updateResearchModal();
}
function finishResearchBriefSave(result,view=researchView,show=true){
  const brief=validBriefRecord(result.brief);applyState(result.state);
  if(view&&researchView===view&&view.ownerId===connection.userId){resetResearchAuthor(view);view.selectedBrief=brief;view.panel='briefs';view.briefsLoaded=false;if(show)updateResearchModal();}
  render();toast('Brief saved. Its content remains unverified.');
}
async function saveResearchBrief(){
  const view=researchView;if(!researchAuthorReady(view)||!api)return;
  const preview=view.briefPreview;
  if(!preview||preview.signature!==authorSignature(view)||preview.revision!==view.authorRevision){view.briefPreview=null;view.briefError='Preview the current draft before saving.';updateResearchModal();return;}
  const payload=structuredClone(preview.payload),owner=view.ownerId,serial=researchSerial,generation=editorGeneration;
  const beforeSend=()=>researchCurrent(view,serial)&&view.panel==='import'&&view.briefPreview===preview&&authorSignature(view)===preview.signature&&editorGeneration===generation;
  const ownerCurrent=()=>{if(connection.userId!==owner){if(researchView===view){clearResearch();closeModal();}return false;}return connection.status==='ready';};
  await task(async()=>{
    let result;try{result=await request(preview.methodWorkId?'/api/research/methods/complete':'/api/research/briefs',preview.methodWorkId?{workId:preview.methodWorkId,brief:payload}:payload,'POST',{beforeSend,isCurrent:ownerCurrent,validateResult:result=>preview.methodWorkId?validateResearchCompletion(result,preview.methodWorkId):validateBriefSave(result)});}catch(error){if(!ownerCurrent())return;throw error;}if(!result||!ownerCurrent())return;
    finishResearchBriefSave(result,view,researchModalOpen&&researchSerial===serial&&view.panel==='import');
  });
}


// Saved-research checks keep the final assessment supplied by the user's agent.
function researchPortfolioAvailable(){return portfolioLocal()&&connection.researchPortfolio===true;}
async function researchRecordDigest(value){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(portfolioCanonicalUI(value)));return [...new Uint8Array(bytes)].map(x=>x.toString(16).padStart(2,'0')).join('');}
function researchProvenanceMarkup(h){if(!h)return '';return `<section><h3>Research behind this proposal</h3><p>Saved research version ${h.researchRef.version} · ${esc(shortDate(h.researchRef.createdAt))}. Sources and the agent’s assessment remain unverified.</p><ul>${h.gaps.filter(g=>g.code==='retained-research-gap').map(g=>`<li>${esc(g.detail)}</li>`).join('')}</ul><details class="record-details"><summary>Exact research and source references</summary><pre>${esc(JSON.stringify({research:h.researchRef,approach:h.researchWorkRef||null,sources:h.sourceMapping},null,2))}</pre></details></section>`;}
function researchPortfolioMarkup(){const v=portfolioView(),r=v.researchDraft;if(!r)return '';return `<section class="research-memory"><h2>Check this research against my portfolio</h2><p>${esc(r.brief.question)} · version ${r.brief.version}</p><p>Ask your agent to assess this saved research using your portfolio values and existing targets. Add its completed review below, then inspect the proposal before saving. Nothing is fetched or traded.</p><div class="actions">${button('Copy request for my agent','research-portfolio-copy','secondary')}</div><label for="research-portfolio-baseline">Compare with an earlier proposal</label><select id="research-portfolio-baseline"><option value="">First proposal</option>${[...(state.portfolioWorks||[]),...(state.portfolioArchive?.entries||[])].map(w=>`<option value="${esc(w.id)}" ${v.previousWorkId===w.id?'selected':''}>${esc(shortDate(w.createdAt))} · ${esc(w.id.slice(0,8))}</option>`).join('')}</select><p class="field-help">The selected proposal’s targets and limits must stay unchanged.</p><label for="research-portfolio-file">Add your agent’s portfolio review</label><input type="file" id="research-portfolio-file" accept="application/json,.json"><p class="field-help">Choose the assessment file your agent prepared for this saved version.</p><details class="record-details"><summary>Advanced JSON</summary><label for="research-portfolio-json">Agent’s review</label><textarea id="research-portfolio-json" rows="12" maxlength="262144" spellcheck="false">${esc(v.researchText||'')}</textarea></details><div class="actions">${button('Preview proposal','research-portfolio-preview','primary',v.researchText?'':'disabled')}${button('Discard draft','portfolio-discard','ghost small')}</div><p class="field-help">No Angbao account is required. Unsaved reviews stay in this session and are lost on reload.</p></section>`;}
async function openResearchPortfolio(id,previousWorkId=null){if(!researchPortfolioAvailable())return;await portfolioAction(async current=>{const v=portfolioView();if(v.dirty||researchView.importDirty)throw clientError('Save or discard the current draft before opening another brief.');const result=await requestBriefRead('/api/research/briefs/'+encodeURIComponent(id),current);if(!current()||!result)return;const brief=validBriefRecord(result.data.brief);if(brief.id!==id)throw clientError('A different research version was returned. Reopen the saved brief.');const digest=await researchRecordDigest(brief);if(!current())return;Object.assign(v,{researchDraft:{brief,digest},researchText:'',draft:null,selected:null,preview:null,previousWorkId,dirty:true,archivePanel:false});researchView.panel='portfolio';});}
async function copyResearchPortfolioRequest(){await portfolioAction(async current=>{const v=portfolioView(),r=v.researchDraft;if(!r)return;let previous=null,methodWork=null;if(v.previousWorkId){previous=(await portfolioRead('/api/local/portfolio-work/'+encodeURIComponent(v.previousWorkId))).data.work;if(!current())return;}if(r.brief.methodRunRef){const response=await workspaceFetch('/api/research/methods/'+encodeURIComponent(r.brief.methodRunRef.workId),{credentials:'same-origin',cache:'no-store',redirect:'error',signal:AbortSignal.timeout(12000)}),data=await readAgentAccessJSON(response);if(!current())return;if(!response.ok||data.work?.id!==r.brief.methodRunRef.workId)throw clientError('The saved research approach is unavailable. Reopen its original work.');methodWork=data.work;}
 const pack={task:'Assess this exact saved research against my supplied portfolio and existing owner targets. Ask for missing values; do not infer positions, prices, source dates, asset identities or targets. Do not fetch, trade, schedule or save without my request. Return a JSON file for Angbao research-portfolio preview. Preserve every supporting/counterclaim, inference and gap. Classify every source explicitly; unread citations stay link-only. Retained summaries stay derived summaries. You may read the local angbao_preview_research_portfolio tool schema and portfolio-decision sample for field structure; synthetic sample values are not my portfolio.',brief:r.brief,reference:{briefId:r.brief.id,expectedBriefDigest:r.digest,...(methodWork?{researchWorkId:methodWork.id,expectedResearchWorkDigest:await researchRecordDigest(methodWork)}:{})},...(methodWork?{researchWork:methodWork}:{}),...(previous?{previousWorkId:previous.id,previousProposal:previous,requiredPolicy:previous.decision.snapshots.policy}:{}),requiredFields:['briefId','expectedBriefDigest','evidenceBindings','assessment','portfolio','policy','asOf'],evidenceBindingFields:{evidenceId:'Exact saved evidence ID',source:['sourceId','version','channel','capture','contentKind','url','text','publishedAt','observedAt'],workCardRef:'If using completed research work: exact packDigest, provider, recordId'},return:'Preview with angbao agent research-portfolio preview --file FILE. Show the proposal and gaps before asking to save. Keep the returned preview file for exact save; continue with angbao agent portfolio read --id WORK_ID.'};if(!current())return;const text=JSON.stringify(pack,null,2);if(!await copy(text))throw clientError('Copy was not available. Keep this brief open and use your agent’s saved-work tools.');});}
function setResearchPortfolioText(text){const v=portfolioView();if(!v.researchDraft||!researchPortfolioAvailable()||researchView.loading||busy||pendingRequest||syncIssue)return;if(typeof text!=='string'||new TextEncoder().encode(text).byteLength>256*1024){v.error='This review is too large. Keep the original file and ask your agent for a smaller review.';updateResearchModal();return;}v.researchText=text;v.dirty=true;v.preview=null;v.error=null;}
async function readResearchPortfolioFile(file){if(!file)return;const v=portfolioView(),view=researchView,owner=connection.userId,draft=v.researchDraft;if(!draft||!researchPortfolioAvailable()||view.loading||busy||pendingRequest||syncIssue)return;try{if(file.size>256*1024)throw clientError('This review is too large. Nothing was loaded.');const text=await file.text();if(researchView!==view||v.researchDraft!==draft||connection.userId!==owner||!researchPortfolioAvailable()||view.loading||busy||pendingRequest||syncIssue)return;setResearchPortfolioText(text);}catch(error){if(researchView===view)v.error=error.message||'The review file could not be read.';}if(researchView===view)updateResearchModal();}
async function previewResearchPortfolio(){await portfolioAction(async current=>{const v=portfolioView(),r=v.researchDraft,text=v.researchText;if(!r||!text)return;let args;try{args=JSON.parse(text);}catch{throw clientError('This review file is incomplete. Ask your agent for the complete assessment.');}if(!args||typeof args!=='object'||Array.isArray(args)||args.briefId!==r.brief.id||args.expectedBriefDigest!==r.digest||args.previousWorkId!==undefined&&args.previousWorkId!==v.previousWorkId)throw clientError('This review belongs to a different research version or earlier proposal. Keep this draft and ask your agent to use the copied request.');delete args.previousWorkId;if(v.previousWorkId)args.previousWorkId=v.previousWorkId;const result=await portfolioRead('/api/local/research-portfolio/preview',args);if(!current()||v.researchText!==text)return;if(result.etag!==workspaceETag)throw clientError('The saved workspace changed. Keep this review and refresh before saving.');if(result.data.handoff?.researchRef?.recordId!==r.brief.id||result.data.handoff?.researchRef?.digest!==r.digest||result.data.handoff?.financialAuthority!==false||result.data.saved!==false)throw clientError('This research preview could not be confirmed.');v.preview={handoff:result.data.handoff,decision:result.data.decision,comparison:result.data.comparison,previousWorkId:v.previousWorkId,etag:result.etag};});}

// Local portfolio checks live within Research. Reasoning is supplied by the user's agent.
function portfolioLocal(){return api&&connection.mode==='local'&&connection.status==='ready';}
function portfolioAvailable(){return portfolioLocal()||api&&hosted()&&connection.status==='ready'&&connection.portfolioProposals===true;}
function portfolioPath(path='/api/local/portfolio-work'){return hosted()?path.replace('/api/local/portfolio-work','/api/portfolio-work'):path;}
function portfolioView(){if(!researchView.portfolio)researchView.portfolio={works:[],selected:null,draft:null,preview:null,dirty:false,mode:'guided',json:'',error:null,previousWorkId:null};return researchView.portfolio;}
const portfolioCanonicalUI=value=>Array.isArray(value)?`[${value.map(portfolioCanonicalUI).join(',')}]`:value&&typeof value==='object'?`{${Object.keys(value).sort().map(key=>`${JSON.stringify(key)}:${portfolioCanonicalUI(value[key])}`).join(',')}}`:JSON.stringify(value);
function portfolioBlank(){const now=new Date().toISOString();return {mode:'manual',currency:'USD',asOf:now,source:{channel:'manual',contentKind:'link-only',url:'',text:'',publishedAt:'',observedAt:now},positions:[{id:'asset-1',kind:'listed-equity',exchange:'',ticker:'',value:'',targetPct:'',focus:false,relation:'context-only'}],cash:'',committed:'',reserve:'',spendCap:'',fee:'',cashTargetPct:'',snapshotAt:now,maxSnapshotAgeHours:'24',maxSourceAgeHours:'168',assessment:{intent:'research',supporting:'',contradicting:'',inference:'',gap:''},dca:{installments:'1',cadence:'monthly'}};}
function portfolioDate(value){if(!value)return '';const date=new Date(value);if(!Number.isFinite(date.getTime()))return '';date.setMinutes(date.getMinutes()-date.getTimezoneOffset());return date.toISOString().slice(0,16);}
function portfolioISO(value){if(!value)return '';const date=new Date(value);return Number.isFinite(date.getTime())?date.toISOString():value;}
function portfolioStatus(value){return ({'prepare-allocation':'Contribution proposal','prepare-DCA':'Split contribution proposal',watch:'Watch',research:'More research needed',blocked:'Check the inputs'})[value]||'Portfolio check';}
function portfolioAsset(item){const i=item.identity||item;return item.kind==='listed-equity'?`${i.ticker||'Stock'} · ${i.exchange||'exchange unknown'}`:item.kind==='tokenized-equity'?`Tokenized stock · ${i.issuer||'issuer unknown'}`:`Crypto · ${i.network||'network unknown'}`;}
function portfolioMoney(value,currency,exponent){if(value===null||value===undefined)return 'Unknown';try{return new Intl.NumberFormat(undefined,{style:'currency',currency}).format(value/10**exponent);}catch{return 'Unknown';}}
function portfolioGap(gap){return ({'allocation-target-total':'Your target percentages, including cash, must add to 100%.','portfolio-cash-unknown':'Enter your cash and existing commitments.','position-value-unknown':'Enter a value for every position; use zero only when you know it is zero.','policy-budget-unknown':'Enter your reserve, spending cap and fee allowance.','allocation-target-unknown':'Enter a target percentage for every position.','cash-target-unknown':'Enter your cash target percentage.','instrument-identity-noncanonical':'Confirm the exact exchange and stock symbol, or the network and asset address.','instrument-identity-unknown':'Complete the identity of each asset; a symbol alone can be ambiguous.','target-instrument-identity-missing':'Confirm the exact identity of each asset before using its target.','source-text-unavailable':'A link has not been read. Supply the text or excerpt before calculating a contribution.','counterevidence-missing':'Add your agent’s counterevidence or its explicit note about what remains unchecked.','portfolio-stale':'These portfolio values are older than your selected limit. Recheck them before sizing.','source-stale':'The source is older than your selected limit. Recheck it before sizing.'})[gap.code]||gap.detail;}
function portfolioProposalMarkup(decision,comparison){
 const snapshot=decision.snapshots,p=snapshot.portfolio,policy=snapshot.policy,plan=decision.plan,currency=p?.currency||'USD',exponent=p?.minorUnitExponent??2,fmt=value=>portfolioMoney(value,currency,exponent);
 return `<article class="research-memory"><h2>${esc(portfolioStatus(decision.status))}</h2><p>${esc(decision.reason)}</p><p class="field-help">${p?.source==='sample'?'Synthetic example':'Manually supplied values'} · Unverified · Nothing is traded, scheduled or reserved.</p>${plan?`<section><h3>Proposed contribution</h3><p>${esc(fmt(plan.investmentMinor))} from existing cash, plus up to ${esc(fmt(plan.feeAllowanceMinor))} in fees.</p><p>Cash after the contribution: ${esc(fmt(plan.cashAfterInvestmentMinor))}; ${esc(fmt(plan.cashAfterIfFullFeeAllowanceSpentMinor))} if the full fee allowance is used.</p><ul>${plan.allocations.map(allocation=>`<li>${esc(portfolioAsset(p.positions.find(item=>item.instrument.id===allocation.instrumentId)?.instrument||{}))}: ${esc(fmt(allocation.amountMinor))}</li>`).join('')}</ul>${plan.dca?`<h3>Proposed split</h3><p>${plan.dca.installmentCount} ${esc(plan.dca.cadence)} planning steps. Each step needs fresh inputs and a separate decision; no job is scheduled.</p><ol>${plan.dca.installments.map(step=>`<li>${esc(fmt(step.investmentMinor))}</li>`).join('')}</ol>`:''}</section>`:'<p>No contribution amount is proposed.</p>'}${decision.comparison?`<section><h3>Current allocation and your targets</h3><table><thead><tr><th>Asset</th><th>Current</th><th>Target</th></tr></thead><tbody>${decision.comparison.positions.map(row=>`<tr><td>${esc(portfolioAsset(p.positions.find(item=>item.instrument.id===row.instrumentId)?.instrument||{}))}</td><td>${(row.currentWeightBpsFloor/100).toFixed(2)}%</td><td>${(row.targetBps/100).toFixed(2)}%</td></tr>`).join('')}</tbody></table></section>`:''}${comparison?.baselineId?`<section><h3>What changed since the selected proposal</h3><p>${comparison.changes?.length?comparison.changes.map(item=>esc(item.label)).join(', '):'The saved inputs are unchanged.'}</p>${comparison.amounts?`<p>Contribution: ${esc(portfolioMoney(comparison.amounts.before,comparison.amounts.currency,comparison.amounts.minorUnitExponent))} → ${esc(portfolioMoney(comparison.amounts.after,comparison.amounts.currency,comparison.amounts.minorUnitExponent))}.</p>`:'<p>The inputs need review before comparing contribution amounts.</p>'}</section>`:comparison?.status==='baseline-unavailable'?'<p>The selected earlier proposal is unavailable; another baseline was not substituted.</p>':''}<section><h3>Your agent’s assessment</h3>${snapshot.assessment?.claims?.map(claim=>`<p><strong>${esc(({supporting:'Supporting',contradicting:'Counterevidence',uncertain:'Uncertain'})[claim.stance])}</strong> ${esc(claim.text)}</p>`).join('')||'<p>No assessment has been supplied.</p>'}${snapshot.assessment?.inferences?.map(item=>`<p>Inference: ${esc(item.text)}</p>`).join('')||''}</section><section><h3>Supplied sources</h3>${snapshot.sources.map(source=>`<p>${source.url?`<a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${esc(source.channel)}</a>`:esc(source.channel)} · ${source.contentKind==='derived-summary'?'Derived summary':source.contentKind==='link-only'?'Unread link':'Supplied text'}</p>${source.text?`<p>${esc(source.text)}</p>`:''}`).join('')}</section><section><h3>What still needs checking</h3><ul>${decision.gaps.map(gap=>`<li>${esc(portfolioGap(gap))}</li>`).join('')}${(snapshot.assessment?.gaps||[]).map(gap=>`<li>${esc(gap)}</li>`).join('')}</ul></section><details class="record-details"><summary>Approach and saved inputs</summary><p>These targets were supplied for this check. Saving them is not approval to act.</p><pre>${esc(JSON.stringify({method:decision.method,asOf:decision.asOf,portfolio:p,policy,references:decision.references,truth:decision.truth},null,2))}</pre></details></article>`;
}
function portfolioArchiveMarkup(){const v=portfolioView(),preview=v.archivePreview||v.importPreview;return `<section class="research-memory"><h2>Archived proposals</h2><p>Keep older proposals and their exact comparisons without using an active slot. Archiving is free and does not delete history. This local archive has a 64-proposal safety bound.</p>${v.error?`<p role="alert">${esc(v.error)}</p>`:''}${preview?`<h3>Review before saving</h3><p>${v.importPreview?'Import into the archive':preview.action==='archive'?'Move to the archive':'Restore to active proposals'} · ${(preview.ids||preview.importedIds||[]).length} proposals.</p><p>Existing settings and financial permissions stay unchanged. No transaction is replayed.</p><details><summary>Selected records and dependencies</summary><pre>${esc(JSON.stringify(preview,null,2))}</pre></details>${button('Confirm','archive-commit','primary')}${button('Back','archive-open','secondary')}`:`<div class="actions">${button('Export portfolio history','archive-export','secondary')}${button('Active proposals','portfolio-list','secondary')}</div><label for="history-import">Restore from a portfolio-history export</label><input type="file" id="history-import" accept="application/json,.json"><p class="field-help">Choose the original private bundle. You will preview conflicts before anything is saved.</p><ul class="object-list">${(v.archiveEntries||[]).map(e=>`<li>${button('Open proposal · '+esc(shortDate(e.createdAt)),'portfolio-read','text-button',`data-id="${esc(e.id)}"`)}</li>`).join('')||'<li>No archived proposals yet.</li>'}</ul>`}</section>`;}
async function archiveRead(action='',body){if(!portfolioLocal()||pendingRequest||syncIssue)throw clientError('Confirm the current save before opening history.');const context=workspaceContext(),response=await workspaceFetch('/api/local/history-archive'+action,{method:body?'POST':'GET',headers:body?{'content-type':'application/json'}:{},credentials:'same-origin',cache:'no-store',redirect:'error',...(body?{body:JSON.stringify(body)}:{})});const data=await readAgentAccessJSON(response,4*1024*1024);assertWorkspaceContext(context);if(!response.ok)throw clientError(data.error?.message||'History could not be opened.');return data;}
async function openPortfolioArchive(){await portfolioAction(async current=>{if(portfolioView().dirty)throw clientError('Save or discard the draft before changing history.');const data=await archiveRead();if(!current())return;Object.assign(portfolioView(),{archiveEntries:data.archive.entries,archivePanel:true,archivePreview:null,importPreview:null,importBundle:null,error:null});});}
async function previewPortfolioArchive(id){await portfolioAction(async current=>{const action=(state.portfolioArchive?.entries||[]).some(e=>e.id===id)?'restore':'archive',preview=await archiveRead('/preview',{action,ids:[id]});if(!current())return;if(preview.format!=='angbao-history-preview@1'||preview.financialAuthority!==false)throw clientError('The archive preview could not be confirmed.');Object.assign(portfolioView(),{archivePanel:true,archivePreview:preview,importPreview:null});});}
function validateArchiveSave(result){if(!result.archiveResult||result.archiveResult.financialAuthority!==false||result.archiveResult.recordsDeleted!==false||!result.state?.localInstallation?.id)throw clientError('The history save is unconfirmed. Keep its original request before retrying.');return result;}
async function commitPortfolioArchive(){const v=portfolioView(),p=v.importPreview||v.archivePreview;if(!p||!portfolioLocal()||pendingRequest||syncIssue)return;await task(async()=>{const body=v.importPreview?{bundle:v.importBundle,previewDigest:p.previewDigest}:{action:p.action,ids:p.ids,previewDigest:p.previewDigest},result=await request('/api/local/history-archive/'+(v.importPreview?'import':'commit'),body,'POST',{validateResult:validateArchiveSave});if(!result)return;applyState(result.state);Object.assign(v,{archivePreview:null,importPreview:null,importBundle:null,selected:null});const savedIndex=await archiveRead();v.archiveEntries=savedIndex.archive.entries;v.archivePanel=true;updateResearchModal();render();toast('History saved. No records were deleted.');});}
async function exportPortfolioArchive(){await task(async()=>{const bundle=await archiveRead('/export');if(bundle.format!=='angbao-portfolio-history-bundle@1'||bundle.manifest.financialAuthority!==false)throw clientError('The history export could not be confirmed.');download(bundle,'angbao-portfolio-history-'+today()+'.json');toast('Portfolio history downloaded. Keep it private.');});}
document.addEventListener('change',event=>{if(event.target.id!=='history-import')return;const file=event.target.files?.[0];if(!file)return;void portfolioAction(async current=>{if(file.size>4*1024*1024)throw clientError('Use the original history bundle within 4 MiB.');let bundle;try{const value=JSON.parse(await file.text());bundle=value.portfolioHistory||value;}catch{throw clientError('Choose a valid portfolio-history JSON export.');}const preview=await archiveRead('/import-preview',{bundle});if(!current())return;Object.assign(portfolioView(),{archivePanel:true,archivePreview:null,importPreview:preview,importBundle:bundle});});});
function portfolioSelect(label,name,value,options){const choices=value&&!options.some(([id])=>id===value)?[...options,[value,`Supplied value: ${value}`]]:options;return `<div class="field"><label for="${esc(name)}">${esc(label)}</label><select id="${esc(name)}" name="${esc(name)}">${choices.map(([id,text])=>`<option value="${esc(id)}" ${value===id?'selected':''}>${esc(text)}</option>`).join('')}</select></div>`;}
function portfolioField(label,name,value,type='text'){return field(label,name,value??'',`type="${type}" ${type==='number'?'min="0" step="any"':''} maxlength="200"`);}
function portfolioText(label,name,value,max=1500){return `<div class="field"><label for="${esc(name)}">${esc(label)}</label><textarea id="${esc(name)}" name="${esc(name)}" rows="3" maxlength="${max}">${esc(value||'')}</textarea></div>`;}
function portfolioFormMarkup(view){
 const d=view.draft;if(view.mode==='json')return `<form data-form="portfolio"><h3>Portfolio input JSON</h3><p class="field-help">Includes financial data. Keep it private. Preview checks the complete supplied snapshots without fetching sources or changing targets.</p><textarea name="portfolio-json" id="portfolio-json" rows="18" maxlength="65536">${esc(view.json)}</textarea><div class="actions"><button class="button primary" type="submit">Preview proposal</button>${button('Use guided form','portfolio-guided','secondary small')}${button('Discard draft','portfolio-discard','ghost small')}</div></form>`;
 const networks=[['','Select a network'],['eip155:1','Ethereum'],['eip155:8453','Base'],['eip155:42161','Arbitrum'],['eip155:46630','Robinhood test network (sample)']];
 return `<form data-form="portfolio"><p class="field-help">${d.mode==='sample'?'Synthetic example. It does not replace your saved figures or targets.':'Use values you checked yourself. No financial account or market price is connected.'}</p><h3>Source you or your agent supplied</h3><div class="field-row">${portfolioSelect('Source','pf-source-channel',d.source.channel,[['manual','Manual note'],['article','Article'],['x','X post'],['telegram','Telegram'],['substack','Substack'],['news','News']])}${portfolioSelect('What was supplied','pf-source-contentKind',d.source.contentKind,[['link-only','Link only · not read'],['source-excerpt','Source excerpt'],['source-text','Source text'],['derived-summary','Derived summary']])}</div>${portfolioField('Public source link (optional)','pf-source-url',d.source.url)}${portfolioText('Supplied source text or excerpt','pf-source-text',d.source.text,8000)}<div class="field-row">${portfolioField('When was it supplied?','pf-source-observedAt',portfolioDate(d.source.observedAt),'datetime-local')}${portfolioField('Publication time, if known','pf-source-publishedAt',portfolioDate(d.source.publishedAt),'datetime-local')}</div><h3>Portfolio values and your targets</h3>${portfolioSelect('Valuation currency','pf-currency',d.currency,[['USD','USD'],['SGD','SGD'],['EUR','EUR'],['GBP','GBP'],['JPY','JPY'],['KWD','KWD']])}<div class="field-row">${portfolioField('Cash','pf-cash',d.cash,'number')}${portfolioField('Cash already committed','pf-committed',d.committed,'number')}${portfolioField('Cash target (%)','pf-cashTargetPct',d.cashTargetPct,'number')}</div>${portfolioField('When were these values checked?','pf-snapshotAt',portfolioDate(d.snapshotAt),'datetime-local')}${d.positions.map((position,index)=>`<fieldset class="record-details"><legend>Position ${index+1}</legend>${portfolioSelect('Asset type',`pf-${index}-kind`,position.kind,[['listed-equity','Listed stock'],['tokenized-equity','Tokenized stock'],['crypto','Crypto']])}${position.kind==='listed-equity'?`<div class="field-row">${portfolioSelect('Exchange',`pf-${index}-exchange`,position.exchange,[['','Select exchange'],['XNAS','NASDAQ'],['XNYS','NYSE'],['XSES','SGX'],['XLON','London']])}${portfolioField('Stock symbol',`pf-${index}-ticker`,position.ticker)}</div>`:`${portfolioSelect('Network',`pf-${index}-network`,position.network,networks)}${position.kind==='tokenized-equity'?`${portfolioField('Token contract address',`pf-${index}-contractAddress`,position.contractAddress)}${portfolioField('Token issuer',`pf-${index}-issuer`,position.issuer)}${portfolioSelect('Underlying listed stock',`pf-${index}-underlyingListedId`,position.underlyingListedId,[['','Select the underlying stock'],...d.positions.filter(row=>row.kind==='listed-equity').map(row=>[row.id,`${row.ticker||'Stock'} · ${row.exchange||'exchange unknown'}`])])}`:`${portfolioSelect('Asset',`pf-${index}-assetChoice`,position.assetChoice||(position.assetId==='native'?'native':position.assetId?'token':''),[['','Select an asset'],['native','Network asset'],['token','Token contract']])}${(position.assetChoice==='token'||position.assetId&&position.assetId!=='native')?portfolioField('Token contract address',`pf-${index}-assetId`,position.assetId):''}`}`}<div class="field-row">${portfolioField('Position value',`pf-${index}-value`,position.value,'number')}${portfolioField('Your target (%)',`pf-${index}-targetPct`,position.targetPct,'number')}</div><label><input type="checkbox" name="pf-${index}-focus" ${position.focus?'checked':''}> Include this asset in the assessment</label>${portfolioSelect('How your agent relates the source to this target',`pf-${index}-relation`,position.relation,[['context-only','Context only'],['supports-owner-target','Supports the existing target'],['challenges-owner-target','Challenges the existing target']])}${button('Remove position','portfolio-remove','ghost small',`data-id="${index}"`)}</fieldset>`).join('')}<div class="actions">${button('Add position','portfolio-add','secondary small',d.positions.length>=8?'disabled':'')}</div><p class="field-help">All positions and cash use this currency. Targets, including cash, must total 100%. A tokenized stock is a separate asset from its listed stock.</p>${view.previousWorkId?'<p class="field-help">This repeat keeps the selected proposal’s targets and limits. Changes require a separate owner review before sizing.</p>':''}<h3>Limits you supplied for this check</h3><div class="field-row">${portfolioField('Cash reserve to keep','pf-reserve',d.reserve,'number')}${portfolioField('Total spending cap, including fees','pf-spendCap',d.spendCap,'number')}${portfolioField('Fee allowance','pf-fee',d.fee,'number')}</div><details class="record-details"><summary>Freshness limits</summary>${portfolioField('Portfolio values: maximum age in hours','pf-maxSnapshotAgeHours',d.maxSnapshotAgeHours,'number')}${portfolioField('Sources: maximum age in hours','pf-maxSourceAgeHours',d.maxSourceAgeHours,'number')}</details><h3>Your agent’s assessment</h3><p class="field-help">Paste the final assessment from your own agent. Angbao checks references and calculations; it does not write the reasoning or verify the claims.</p>${portfolioSelect('Purpose of this check','pf-assessment-intent',d.assessment.intent,[['research','Continue research'],['watch','Watch'],['prepare-allocation','Prepare a contribution'],['prepare-DCA','Prepare a split contribution'],['review-rebalance','Review a rebalance · no trades prepared']])}${portfolioText('Supporting claim','pf-assessment-supporting',d.assessment.supporting)}${portfolioText('Counterevidence, if supplied','pf-assessment-contradicting',d.assessment.contradicting)}${portfolioText('Inference, if supplied','pf-assessment-inference',d.assessment.inference)}${portfolioText('What your agent says remains unchecked','pf-assessment-gap',d.assessment.gap)}<div class="field-row">${portfolioField('Number of planning steps','pf-dca-installments',d.dca.installments,'number')}${portfolioSelect('Planning interval','pf-dca-cadence',d.dca.cadence,[['daily','Daily'],['weekly','Weekly'],['monthly','Monthly']])}</div><p class="field-help">A split is a proposal only. It schedules nothing and reserves no money.</p><div class="actions"><button type="submit" class="button primary">Preview proposal</button>${button('Discard draft','portfolio-discard','ghost small')}</div><details class="record-details"><summary>Advanced JSON</summary><p>Use the complete typed input from your agent. Added details stay in JSON if the simple form cannot preserve them.</p>${button('Edit JSON','portfolio-json','secondary small')}</details></form>`;
}
function portfolioMarkup(){const view=portfolioView();if(view.archivePanel)return portfolioArchiveMarkup();return `<section class="research-memory"><h2>Check against portfolio</h2><p class="field-help">${hosted()?'Saved in your private account. Uses only the information you supply.':'Optional, saved on this computer. No signup or financial connection is needed.'}</p>${view.error?`<p role="alert">${esc(view.error)}</p>`:''}${researchView.loading?'<p role="status">Checking the supplied proposal…</p>':''}${view.preview?portfolioProposalMarkup(view.preview.decision,view.preview.comparison)+researchProvenanceMarkup(view.preview.handoff)+`<p>Preview only. Nothing has been saved.</p><div class="actions">${button('Save proposal','portfolio-save','primary')}${button('Edit inputs','portfolio-edit','secondary')}</div>`:view.researchDraft?researchPortfolioMarkup():view.draft?portfolioFormMarkup(view):view.selected?portfolioProposalMarkup(view.selected.work.decision,view.selected.comparison)+researchProvenanceMarkup(view.selected.work.researchHandoff)+submissionReviewMarkup(view)+`<div class="actions">${portfolioLocal()?button('Copy for another agent','continue-portfolio','secondary',`data-id="${esc(view.selected.work.id)}"`):''}${button('Check again','portfolio-repeat','secondary')}${portfolioLocal()?button((state.portfolioArchive?.entries||[]).some(e=>e.id===view.selected.work.id)?'Restore to active proposals':'Archive proposal','archive-preview-change','secondary',`data-id="${esc(view.selected.work.id)}"`):''}${button('Saved portfolio checks','portfolio-list','ghost small')}</div>`:`<p>Bring a source and your agent’s assessment. Compare them with your own portfolio values and targets before saving a proposal.</p><div class="actions">${button('Try a portfolio check','portfolio-sample','secondary')}${button('Use my values','portfolio-manual','secondary')}${portfolioLocal()?button('Archived proposals','archive-open','secondary'):''}</div><ul class="object-list">${view.works.map(work=>`<li>${button(esc(portfolioStatus(work.status))+' · '+esc(shortDate(work.createdAt)),'portfolio-read','text-button',`data-id="${esc(work.id)}"`)} <span>${work.source==='sample'?'Sample':'Manual'}</span></li>`).join('')}</ul>`}</section>`;}
function submissionReviewMarkup(view){
 const work=view.selected?.work;if(!portfolioLocal()||!work)return '';const f=view.transferForm||{};const records=(state.submissionReviews||[]).filter(record=>record.localWorkId===work.id);
 let markup=`<section class="record-details"><h3>Test transfer review</h3><p>This optional transfer moves test tokens toward a selected goal. It does not buy the assets in this portfolio proposal or convert its valuation currency. Your wallet must separately approve the exact transfer.</p>${button('Review a test transfer','submission-review-open','secondary')}${button('Decline a new transfer','submission-review-decline','ghost small')}</section>`;
 if(view.reviewForm)markup+=`<form data-form="submission-review"><h3>Test transfer details</h3><p>Robinhood Testnet · Test tokens only. Supply an existing account and verified token details. No address, balance or gas coverage has been checked.</p>${portfolioSelect('Goal','sr-goal',f['sr-goal']||'',[['','Choose a goal'],...state.goals.map(goal=>[goal.id,goal.name])])}${portfolioField('Sending wallet account','sr-account',f['sr-account']||'')}${portfolioField('Test token contract','sr-token',f['sr-token']||'')}<div class="field-row">${portfolioField('Token symbol','sr-symbol',f['sr-symbol']||'')}${portfolioField('Token decimals','sr-decimals',f['sr-decimals']||'','number')}</div>${portfolioField('Recipient wallet','sr-recipient',f['sr-recipient']||'')}${portfolioField('Test token amount','sr-amount',f['sr-amount']||'')}<p class="field-help">Use the token amount, not a cash value. No exchange rate is inferred.</p><button type="submit" class="button primary">Review exact transfer</button>${button('Discard transfer draft','submission-review-discard','ghost small')}</form>`;
 if(view.reviewPreview){const d=view.reviewPreview;markup+=`<section class="record-details"><h3>Confirm your review</h3><p>${esc(d.displayAmount)} ${esc(d.token.symbol)} on Robinhood Testnet</p><dl><dt>From</dt><dd>${esc(d.account)}</dd><dt>To</dt><dd>${esc(d.recipient)}</dd><dt>Token contract</dt><dd>${esc(d.token.address)}</dd><dt>Smallest token units</dt><dd>${esc(d.amountAtomic)}</dd></dl><p>This saves your review intent. It grants no signing permission and sends nothing.</p>${button('Save review and continue','submission-review-save','primary')}</section>`;}
 return markup+goalTransferMarkup(view)+(records.length?`<section><h3>Saved transfer reviews</h3><ul>${records.map(record=>`<li>${record.choice==='decline'?'Declined':'Reviewed for test transfer'} · ${researchTime(record.createdAt)}${record.imported?' · Imported, read only':''}${record.transferDetails?` · ${esc(record.transferDetails.token.symbol)}<p>Recipient: ${esc(record.transferDetails.recipient)}</p>`:''}<p>Local review intent; wallet authorization not established.</p>${record.choice==='prepare-test-transfer'?button('Open transfer','goal-transfer-open','secondary small',`data-id="${esc(record.id)}"`):''}</li>`).join('')}</ul></section>`:'');
}
function previewSubmissionReview(data){try{const raw=String(data.get('sr-amount')||'').trim(),decimals=Number(data.get('sr-decimals'));if(!/^\d+(?:\.\d+)?$/.test(raw)||!Number.isInteger(decimals)||decimals<0||decimals>18||String(data.get('sr-decimals')||'')==='')throw Error();const [whole,fraction='']=raw.split('.');if(fraction.length>decimals)throw Error();const amountAtomic=BigInt(whole+fraction.padEnd(decimals,'0')).toString();if(amountAtomic==='0')throw Error();const details={goalId:String(data.get('sr-goal')||''),chainId:46630,account:String(data.get('sr-account')||'').trim().toLowerCase(),token:{address:String(data.get('sr-token')||'').trim().toLowerCase(),symbol:String(data.get('sr-symbol')||'').trim(),decimals},recipient:String(data.get('sr-recipient')||'').trim().toLowerCase(),amountAtomic,displayAmount:raw};const address=value=>/^0x[a-f0-9]{40}$/.test(value)&&!/^0x0{40}$/.test(value);if(!state.goals.some(goal=>goal.id===details.goalId)||!address(details.account)||!address(details.token.address)||!address(details.recipient)||new Set([details.account,details.token.address,details.recipient]).size!==3||!/^[A-Za-z0-9][A-Za-z0-9._-]{0,11}$/.test(details.token.symbol)||BigInt(amountAtomic)>2n**256n-1n)throw Error();portfolioView().reviewPreview=details;portfolioView().reviewForm=false;portfolioView().dirty=true;portfolioView().error=null;}catch{portfolioView().error='Choose a goal and enter the exact account, token, recipient and positive token amount. Check the token decimals; use separate wallet and token addresses.';}updateResearchModal();}
function transferReviewTime(value){return typeof value==='string'&&Number.isFinite(Date.parse(value))?`<time datetime="${esc(value)}">${esc(new Date(value).toLocaleString(undefined,{dateStyle:'medium',timeStyle:'short'}))}</time>`:'Unavailable';}
function transferTokenAmount(intent){const digits=intent.amountAtomic.padStart(intent.token.decimals+1,'0');return intent.token.decimals?(digits.slice(0,-intent.token.decimals)+'.'+digits.slice(-intent.token.decimals)).replace(/\.?0+$/,''):digits;}
function goalTransferMarkup(view){const review=(state.submissionReviews||[]).find(item=>item.id===view.transferReviewId);if(!review)return '';const record=(state.goalTransfers||[]).find(item=>item.localReviewId===review.id),terms=record?.intent||review.transferDetails;if(!terms)return '';if(record&&connection.directOwnerTestnet)return directTransferMarkup(record);const status=record?({'awaiting-wallet':record.ownerOperation?'Wallet review prepared':'Wallet approval not connected',pending:'Submitted reference · verification pending',uncertain:'Outcome uncertain · do not send again',confirmed:'Confirmed when observed',failed:'Transfer failed'})[record.state]:'Ready for unsigned preparation';
 return `<section class="record-details"><h3>${esc(status)}</h3><p>${esc(transferTokenAmount(terms))} ${esc(terms.token.symbol)} · Robinhood Testnet</p><dl><dt>Sending account</dt><dd>${esc(terms.account)}</dd><dt>Recipient</dt><dd>${esc(terms.recipient)}</dd><dt>Token contract</dt><dd>${esc(terms.token.address)}</dd><dt>Goal</dt><dd>${esc(state.goals.find(goal=>goal.id===terms.goalId)?.name||terms.goalId)}</dd></dl><p>${record?.ownerOperation?'Read the maximum network cost and separate wallet approval below.':'Network cost and gas coverage have not been checked. A local review records your choice; wallet approval is separate.'}</p>${record?ownerFlowMarkup(record):''}${record?`<p>${record.imported?'Imported history is read only.':'Saved on this computer.'} ${record.userOperationHash?'A reported operation hash is not confirmation.':''}</p><details><summary>Operation references and exact call</summary><pre>${esc(JSON.stringify({id:record.id,intentDigest:record.intent.intentDigest,userOperationHash:record.userOperationHash,transactionHash:record.transactionHash,call:record.intent.call,createdAt:record.createdAt,prepareBefore:record.intent.expiresAt},null,2))}</pre></details>${record.state==='awaiting-wallet'?'<p>Unsigned intent saved. A supported owner wallet route, verified test token and gas coverage are still required. The call is not ready to sign. The preparation window does not impose an onchain deadline.</p>':''}${!record.imported&&['awaiting-wallet','pending','uncertain'].includes(record.state)?`<details><summary>Recover a transfer you already submitted</summary><p>Add the exact operation reference from your wallet. Angbao will retain it as unverified. Do not submit a replacement after a timeout.</p><form data-form="goal-transfer-report">${portfolioField('UserOperation hash','gt-userop','')}${portfolioField('Transaction hash, if known','gt-transaction','')}<button type="submit" class="button secondary">Save submitted reference</button></form>${button('Mark outcome uncertain','goal-transfer-uncertain','ghost small',`data-id="${esc(record.id)}"`)}</details>`:''}`:`<p>Review valid for preparation until ${transferReviewTime(review.expiresAt)}. Wallet authorization is separate.</p>${button('Prepare unsigned test transfer','goal-transfer-prepare','secondary',`data-id="${esc(review.id)}" ${Date.parse(review.expiresAt)<=Date.now()||review.imported?'disabled':''}`)}`}</section>`;
}
function resetDirectWallet(){directWallet?.close();directWallet=null;directView=null;}
function directTransferMarkup(record){
 const saved=(state.ownerFundedTransfers||[]).find(item=>item.id===record.id),intent=record.intent,view=directView?.id===record.id?directView:null;
 const label=saved?({'preparing':'Checking the saved transfer','preparation-stopped':'Preparation stopped','review-stopped':'Review stopped · check saved inputs','review-ready':'Ready for your wallet review','wallet-request-uncertain':'Wallet outcome uncertain · do not send again',pending:'Reported transaction · verification pending',confirmed:'Confirmed at the recorded block',failed:'Failed at the recorded block',uncertain:'Verification uncertain · do not send again'})[saved.status]:'Review an owner-funded test transfer';
 let controls='';
 if(!saved&&!record.imported&&record.state==='awaiting-wallet')controls=button('Check transfer and network cost','direct-prepare','secondary',`data-id="${esc(record.id)}"`)+ '<p class="field-help">Uses your existing wallet account and native test ETH. No account deployment or signup. Checking does not send a transaction.</p>';
 if(saved?.status==='review-ready'){const selected=directWallet?.selected();controls=`<p>Maximum network fee: <strong>${esc(networkCost(saved.review.costs.maximumGasFeeWei))}</strong>, paid by ${esc(intent.account)}. Token amount is separate.</p><p>Review expires ${transferReviewTime(saved.review.expiresAt)}.</p><details><summary>Exact network limits</summary><pre>${esc(JSON.stringify(saved.review.transaction,null,2))}</pre></details>${button('Choose wallet','direct-discover','secondary',`data-id="${esc(record.id)}"`)}${view?.providers?.map(provider=>button(esc(provider.name),'direct-select','secondary small',`data-id="${esc(provider.id)}"`)).join('')||''}${selected?`<p>Selected wallet: ${esc(selected.name)}.</p>${selected.connected?button('Approve exact test transfer in wallet','direct-send','primary',`data-id="${esc(record.id)}"`):button('Connect this owner wallet','direct-connect','secondary',`data-id="${esc(record.id)}"`)}`:''}`;}
 if(saved?.nonceReserved){controls+=`<p>This wallet nonce is reserved. After an interruption, check this record rather than sending a replacement.</p>${saved.transactionHash?`<p>Transaction: <code>${esc(saved.transactionHash)}</code></p>${button(saved.observation?'Check receipt again':'Check receipt','direct-observe','secondary',`data-id="${esc(record.id)}"`)}${saved.observation?`<p>${esc(saved.observation.recordedStatus)} · ${saved.observation.summary.confirmations??0} confirmations when observed. Network fee: ${esc(networkCost(saved.observation.summary.fee?.gasCostWei))}.</p><p class="field-help">Historical observation; current confirmation is not assumed after restart.</p>${saved.assetChecks?.at(-1)?.status==='unverified'?'<p>Token implementation identity was not confirmed. A transfer event alone does not establish token value or net balances.</p>':'<p class="field-help">Token code matched at the recorded checkpoint. This does not establish a cash value or finality.</p>'}`:''}`:`<form data-form="direct-reference" data-direct-id="${esc(record.id)}"><p>If your wallet supplied a transaction hash, save that exact reference. This never resends a transfer.</p>${portfolioField('Transaction hash','direct-hash',view?.transactionHash||'')}<button type="submit" class="button secondary">Save reference for verification</button></form>`}`;}
 return `<section class="record-details"><h3>${esc(label)}</h3><p>${esc(transferTokenAmount(intent))} ${esc(intent.token.symbol)} · Robinhood Testnet · Owner-funded</p><dl><dt>From owner wallet</dt><dd>${esc(intent.account)}</dd><dt>Recipient</dt><dd>${esc(intent.recipient)}</dd><dt>Test-token contract</dt><dd>${esc(intent.token.address)}</dd></dl><p>One explicit wallet approval for this exact transfer. No trading, delegation or paid service.</p>${view?.error?`<p role="alert">${esc(view.error)}</p>`:''}${controls}</section>`;
}
async function directAction(action,id,extra={}){if(!portfolioLocal()||!connection.directOwnerTestnet||busy||pendingRequest||syncIssue)return;await task(async()=>{const record=(state.goalTransfers||[]).find(r=>r.id===id),saved=(state.ownerFundedTransfers||[]).find(r=>r.id===id);if(!record||record.imported)return;const body=action==='prepare'?{transferId:id,transferDigest:record.digest,route:'direct-owner-eoa',caps:{gasLimit:'150000',maxFeePerGas:'1000000000',maxPriorityFeePerGas:'100000000'}}:action==='observe'?{id,recheck:extra.recheck===true}:{id,reviewDigest:saved?.review?.reviewDigest,...extra};const result=await request('/api/local/direct-transfer/'+action,body,'POST');if(result?.purpose!=='robinhood-eoa-goal-transfer')throw clientError('This test-transfer reply could not be confirmed.',{protocol:true});applyState(result.state);render();updateResearchModal();});}
function directDiscover(id){if(!portfolioLocal()||!connection.directOwnerTestnet||busy||pendingRequest||syncIssue)return;if(directView?.id!==id){resetDirectWallet();directView={id,providers:[],error:null};}if(!directWallet)directWallet=createWalletProviderSelection({onInvalidated:()=>{if(researchModalOpen)updateResearchModal();}});directView.providers=directWallet.discover();if(!directView.providers.length)directView.error='No wallet is available in this browser. Open this same local address in your wallet browser.';updateResearchModal();}
function directSelect(providerId){if(busy||pendingRequest||syncIssue)return;try{directWallet.select(providerId);directView.error=null;}catch(error){if(directView)directView.error=error.message;}updateResearchModal();}
async function directConnect(id){if(busy||pendingRequest||syncIssue||!portfolioLocal())return;const record=(state.goalTransfers||[]).find(r=>r.id===id);if(!record||directView?.id!==id||!directWallet)return;try{await directWallet.connect({expectedOwner:record.intent.account,chainId:46630});if(directView)directView.error=null;}catch(error){if(directView)directView.error=error.message;}updateResearchModal();}
async function directSend(id){if(!portfolioLocal()||!connection.directOwnerTestnet||directView?.id!==id||!directWallet||busy||pendingRequest||syncIssue)return;const wallet=directWallet,view=directView,record=(state.goalTransfers||[]).find(r=>r.id===id),saved=(state.ownerFundedTransfers||[]).find(r=>r.id===id);if(!record||saved?.status!=='review-ready'||!wallet.selected()?.connected)return;
 await task(async()=>{const start=await request('/api/local/direct-transfer/begin-wallet',{id,reviewDigest:saved.review.reviewDigest},'POST');applyState(start.state);render();updateResearchModal();const c=start.result;if(!c||Object.keys(c).length!==10||!['id','purpose','recordId','reviewDigest','expectedOwner','chainId','transaction','expiresAt','phase','retryAllowed'].every(k=>Object.hasOwn(c,k))||!/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/.test(c.id)||c.purpose!=='robinhood-eoa-goal-transfer'||c.recordId!==id||c.reviewDigest!==saved.review.reviewDigest||c.expectedOwner!==record.intent.account||c.chainId!==46630||c.expiresAt!==saved.review.expiresAt||c.phase!=='review-transaction'||c.retryAllowed!==false||portfolioCanonicalUI(c.transaction)!==portfolioCanonicalUI(saved.review.transaction)||directView!==view||directWallet!==wallet){if(directView===view)view.error='The wallet challenge differs from the displayed review or the review closed. Read saved status; do not send again.';toast('Wallet review not confirmed. Read saved status.','error');updateResearchModal();return;}
  let sent;try{sent=await wallet.sendReviewedTestnetTransfer({purpose:c.purpose,expectedOwner:record.intent.account,chainId:46630,transaction:c.transaction,token:record.intent.token.address,recipient:record.intent.recipient,amountAtomic:record.intent.amountAtomic,expiresAt:c.expiresAt});}catch(error){if(directView===view)view.error='Wallet outcome uncertain. Read this record and your wallet history; do not send another transfer.';toast('Wallet outcome uncertain. No automatic retry.','error');updateResearchModal();return;}
  // Preserve a possibly broadcast hash before reacting to account/network/expiry changes.
  if(directView===view)view.transactionHash=sent.transactionHash;
  try{const result=await request('/api/local/direct-transfer/report',{id,challengeId:c.id,transactionHash:sent.transactionHash},'POST');applyState(result.state);toast(sent.walletContextChanged?'Wallet changed. Transaction reference kept; verify its receipt.':'Transaction reference saved. Check its receipt.');}
  catch{syncIssue={type:'unconfirmed',message:'The wallet returned a transaction hash, but saving its reference was not confirmed. Retry this reference save; do not send another transfer.'};if(directView===view)view.error='Keep this transaction hash: '+sent.transactionHash;toast('Reference save uncertain. Keep '+sent.transactionHash,'error');}
  render();updateResearchModal();
 });
}
function networkCost(value){const raw=String(value??'');if(!/^(0|[1-9][0-9]*)$/.test(raw))return 'Not checked';const padded=raw.padStart(19,'0'),whole=padded.slice(0,-18),fraction=padded.slice(-18).replace(/0+$/,'');return `${whole}${fraction?'.'+fraction:''} ETH`;}
let kernelSetupView=null,kernelWallet=null,kernelWalletBusy=false;
function kernelOverviewMarkup(){if(!portfolioLocal())return '';const records=state.kernelInitializations||[];return `<section class="first-review-panel"><h2>Test account setup</h2><p>Optional. Reviews and research work without a wallet or signup. Creating a test account, adding test tokens and approving a transfer are separate steps.</p>${button('Open account setup','kernel-open','secondary')}${records.length?`<ul>${records.map(record=>`<li>${esc(kernelState(record))} ${button('Continue saved setup','kernel-open','secondary small',`data-id="${esc(record.id)}"`)}</li>`).join('')}</ul>`:''}</section>`;}
function kernelState(record){return ({'awaiting-wallet':'Setup review saved',uncertain:'Setup outcome uncertain · check existing operation',pending:'Account creation pending','deployed-unfunded':'Account verified · needs test tokens',failed:'Account creation failed'})[record.state]||'Saved setup';}
function resetKernelWallet(){const challenge=kernelSetupView?.flow?.walletChallenge;if(challenge)void kernelWalletTransport('cancel',{challengeId:challenge.id}).catch(()=>{});const wallet=kernelWallet;kernelWallet=null;wallet?.close();if(kernelSetupView)kernelSetupView.flow=null;}
async function kernelWalletTransport(action,body){const response=await workspaceFetch(`/api/local/kernel-flow/wallet/${action}`,{method:'POST',headers:{'content-type':'application/json'},credentials:'same-origin',cache:'no-store',body:JSON.stringify(body),signal:AbortSignal.timeout(10000)});const result=await response.json().catch(()=>null);if(!response.ok||result?.walletChallenge?.purpose!=='kernel-account-initialization')throw clientError('The account wallet response was not confirmed. Read saved status; do not resend a signature.');return result.walletChallenge;}
function kernelSelected(){return (state.kernelInitializations||[]).find(record=>record.id===kernelSetupView?.selectedId);}
function kernelSetupMarkup(){const view=kernelSetupView,record=kernelSelected(),operation=record?.initializationOperation,flow=view.flow,challenge=flow?.walletChallenge,selection=kernelWallet?.selected(),expired=record&&Date.parse(record.intent.expiresAt)<=Date.now();
 const prefix='<p>Use a separate test account controlled by your selected wallet. Saving a review creates no account and moves no tokens. Signup is optional.</p>';
 let content='';
 if(record){content=`<h3>${esc(kernelState(record))}</h3><dl><dt>Owner wallet</dt><dd>${esc(record.intent.owner)}</dd><dt>Test account address</dt><dd>${esc(record.intent.account)}</dd><dt>Network</dt><dd>Robinhood Testnet</dd></dl><p>${record.imported?'Imported history is read only. It cannot resume wallet approval or account creation.':'Account creation alone does not establish token funding or permission to transfer.'}</p>${button('Read saved status','kernel-status','secondary small')}${record.imported?'':operation?`<h4>Review account creation</h4><p>Only the standard account initializer and a zero-value empty call are included. No token transfer is included.</p><dl><dt>Maximum network cost</dt><dd>${esc(networkCost(operation.maximumGasCostWei))}</dd><dt>Review expires</dt><dd>${transferReviewTime(operation.expiresAt)}</dd></dl><p>The wallet signs an operation hash and may show only that hash. Read the owner, account and maximum cost here first.</p><details><summary>Gas coverage and exact account operation</summary><pre>${esc(JSON.stringify({sponsorshipEvidence:operation.sponsorshipEvidence,initializationReviewDigest:operation.initializationReviewDigest,userOperationHash:operation.userOperationHash,userOperation:operation.userOperation},null,2))}</pre></details>${flow?.available&&flow.sessionAvailable&&!record.userOperationHash&&!expired?`${button('Find wallets','kernel-discover','secondary small')}${kernelWallet?`<ul>${kernelWallet.list().map(wallet=>`<li>${button(esc(wallet.name),'kernel-select','secondary small',`data-id="${esc(wallet.id)}"`)}${selection?.id===wallet.id?' · Selected':''}</li>`).join('')}</ul>`:''}${selection&&(!challenge||!selection.connected&&challenge.phase!=='signed')?button('Connect selected owner wallet','kernel-connect','secondary'):''}${challenge?`<p>Wallet request: ${esc(challenge.phase)}. Nothing is sent automatically.</p>${challenge.phase==='sign-operation-hash'?button('Approve account creation in wallet','kernel-sign'):''}${challenge.phase==='signed'?button('Create the reviewed test account','kernel-submit'):''}${button('Cancel wallet request','kernel-cancel','ghost small')}`:''}`:'<p>The wallet session is unavailable or the review expired. Read the existing operation before considering another request.</p>'}`:flow?.available&&!record.preparationStatus&&!expired?button('Prepare account creation review','kernel-prepare','secondary'):'<p>Account preparation needs verified factory support and gas coverage. Nothing was created.</p>'}${record.submission&&!record.observationStarted&&flow?.available?button('Check account creation once','kernel-observe','secondary'):''}${record.observationStarted?'<p>The creation check was started. Restarting does not reset its read budget.</p>':''}${record.state==='deployed-unfunded'?'<p>Next: add the supported test tokens to this account, then verify its balance and review a separate transfer. Angbao has not claimed or added tokens.</p>':''}<details><summary>Saved operation references</summary><pre>${esc(JSON.stringify({initializationId:record.id,intentDigest:record.intent.intentDigest,userOperationHash:record.userOperationHash,transactionHash:record.transactionHash,verification:record.verification},null,2))}</pre></details>${expired&&!record.userOperationHash&&!record.submission?button('Review setup again','kernel-renew','secondary'):''}${button('Back to account setups','kernel-new','ghost small')}`;
 }else if(!view.routeAvailable)content='<h3>Test-account setup is not available yet</h3><p>A verified factory route and gas coverage are still needed. You can continue using reviews and research. No wallet connection or signup is required.</p>';
 else if(view.preview)content=`<h3>Preview your test account</h3><dl><dt>Owner wallet</dt><dd>${esc(view.preview.intent.owner)}</dd><dt>Account address</dt><dd>${esc(view.preview.account)}</dd><dt>Network</dt><dd>Robinhood Testnet</dd></dl><p>The same owner and standard account settings determine this address. Network cost and gas coverage are checked separately before wallet approval.</p>${button('Save account setup review','kernel-save')}${button('Change owner wallet','kernel-new','ghost small')}`;
 else content=`<p>Choose the owner wallet for this test account. Connecting reads its public address and selected network; it does not request a signature.</p>${button('Find wallets','kernel-discover','secondary small')}${kernelWallet?`<ul>${kernelWallet.list().map(wallet=>`<li>${button(esc(wallet.name),'kernel-select','secondary small',`data-id="${esc(wallet.id)}"`)}${selection?.id===wallet.id?' · Selected':''}</li>`).join('')}</ul>${selection?button('Read selected wallet address','kernel-read-owner','secondary'):''}`:''}<form data-form="kernel-owner">${portfolioField('Owner wallet address','kernel-owner',view.owner||'')}<button class="button primary" type="submit">Preview test account</button></form>`;
 return prefix+content+(!record&&(state.kernelInitializations||[]).length?`<h3>Saved account setups</h3><ul>${state.kernelInitializations.map(item=>`<li>${esc(kernelState(item))} ${button('Open saved setup','kernel-open','secondary small',`data-id="${esc(item.id)}"`)}</li>`).join('')}</ul>`:'');}
function renderKernelSetup(){if(kernelSetupView)openModal('Test account setup',kernelSetupMarkup(),'',true);}
async function openKernelSetup(id=null){if(!portfolioLocal()||busy||pendingRequest||syncIssue)return;if(hasLocalEdits()){toast('Save or discard your current draft before opening account setup.','error');return;}resetKernelWallet();kernelSetupView={selectedId:id,preview:null,owner:'',routeAvailable:false,flow:null};renderKernelSetup();await task(async()=>{const result=await request('/api/local/kernel-initializations');applyState(result.state);kernelSetupView.routeAvailable=result.routeAvailable===true;if(id){const status=await request(`/api/local/kernel-flow?initializationId=${encodeURIComponent(id)}`);applyState(status.state);kernelSetupView.flow=status;}renderKernelSetup();});}
async function previewKernelOwner(data){if(!kernelSetupView||busy||pendingRequest||syncIssue)return;const owner=String(data.get('kernel-owner')||'').trim().toLowerCase();await task(async()=>{const result=await request('/api/local/kernel-initializations/preview',{owner});if(result.preview?.purpose!=='kernel-account-initialization'||result.preview.intent?.owner!==owner||result.preview.intent?.chainId!==46630||result.preview.workspaceETag!==workspaceETag||result.preview.deploymentAllowed!==false||result.preview.transferReady!==false)throw clientError('The account preview could not be confirmed.',{protocol:true});kernelSetupView.owner=owner;kernelSetupView.preview=result.preview;renderKernelSetup();});}
function validateKernelSave(result){const record=result.state?.kernelInitializations?.find(item=>item.id===result.initializationId);if(!record||record.digest!==result.initializationDigest||record.purpose!=='kernel-account-initialization'||record.financialAuthority!==false)throw clientError('The account setup save was not confirmed. Read saved status before continuing.');return record;}
async function kernelSavedAction(action){if(!kernelSetupView||busy||pendingRequest||syncIssue||kernelWalletBusy)return;const record=kernelSelected();await task(async()=>{let result;if(action==='save'){const preview=kernelSetupView.preview;if(!preview||preview.workspaceETag!==workspaceETag)return;result=await request('/api/local/kernel-initializations',{owner:preview.intent.owner,workspaceId:preview.workspaceId,workspaceETag:preview.workspaceETag},'POST',{validateResult:result=>{const saved=validateKernelSave(result);if(saved.intent.account!==preview.account||saved.intent.owner!==preview.intent.owner||saved.intent.routeEvidenceDigest!==preview.intent.routeEvidenceDigest)throw clientError('The saved account differs from its preview.',{protocol:true});}});}else{if(!record||record.imported)return;result=await request(`/api/local/kernel-flow/${action}`,{initializationId:record.id,initializationDigest:record.digest,...(['begin-wallet','submit'].includes(action)?{initializationReviewDigest:record.initializationOperation?.initializationReviewDigest}:{})},'POST',{validateResult:validateKernelSave});}const saved=validateKernelSave(result);applyState(result.state);kernelSetupView.selectedId=saved.id;kernelSetupView.preview=null;kernelSetupView.flow=result.kernelFlow||null;renderKernelSetup();render();});}
async function readKernelStatus(){const record=kernelSelected();if(!record)return;const result=await request(`/api/local/kernel-flow?initializationId=${encodeURIComponent(record.id)}`);if(kernelSetupView?.selectedId!==record.id)return;applyState(result.state);kernelSetupView.flow=result;renderKernelSetup();}
async function kernelUI(action,id){try{await kernelUIAction(action,id);}catch{toast('The account setup action could not be confirmed. Read saved status before continuing.','error');}}
async function kernelUIAction(action,id){if(!kernelSetupView||busy||pendingRequest||syncIssue||kernelWalletBusy)return;if(action==='new'){resetKernelWallet();Object.assign(kernelSetupView,{selectedId:null,preview:null,owner:'',flow:null});renderKernelSetup();return;}if(action==='renew'){const record=kernelSelected();if(!record||record.imported||record.userOperationHash||record.submission||Date.parse(record.intent.expiresAt)>Date.now())return;resetKernelWallet();Object.assign(kernelSetupView,{selectedId:null,preview:null,owner:record.intent.owner,flow:null});renderKernelSetup();return;}if(action==='status'){await task(readKernelStatus);return;}if(['save','prepare','submit','observe'].includes(action)){await kernelSavedAction(action);return;}if(action==='cancel'){resetKernelWallet();renderKernelSetup();return;}
 if(action==='discover'){if(!kernelWallet)kernelWallet=createWalletProviderSelection({onInvalidated:reason=>{if(reason==='connecting'||reason==='closed'||reason==='selection-changed'&&(!kernelWallet?.selected()||!kernelSetupView?.flow?.walletChallenge))return;const challenge=kernelSetupView?.flow?.walletChallenge;if(challenge)void kernelWalletTransport('cancel',{challengeId:challenge.id}).catch(()=>{});if(kernelSetupView){kernelSetupView.flow=null;kernelSetupView.preview=null;}toast('Wallet or network changed. Read and review the saved account setup again.','error');renderKernelSetup();}});kernelWallet.discover();renderKernelSetup();return;}if(action==='select'){kernelWallet?.select(id);renderKernelSetup();return;}
 if(action==='read-owner'){if(!kernelWallet)return;kernelWalletBusy=true;try{const selection=await kernelWallet.connectOwner();kernelSetupView.owner=selection.owner;kernelSetupView.preview=null;}finally{kernelWalletBusy=false;renderKernelSetup();}return;}
 const record=kernelSelected(),operation=record?.initializationOperation;if(!operation||!kernelWallet||!kernelSetupView.flow?.sessionAvailable)return;
 if(action==='connect'){kernelWalletBusy=true;try{await kernelWallet.connect({expectedOwner:operation.owner,chainId:46630});}finally{kernelWalletBusy=false;}if(!kernelSetupView.flow?.walletChallenge)await kernelSavedAction('begin-wallet');const challenge=kernelSetupView.flow?.walletChallenge;if(challenge?.phase==='check-wallet'){try{kernelSetupView.flow.walletChallenge=await kernelWalletTransport('respond',{challengeId:challenge.id,response:{account:operation.owner,chainId:46630}});}catch{await readKernelStatus();}}renderKernelSetup();return;}
 if(action==='sign'){const challenge=kernelSetupView.flow?.walletChallenge;if(!challenge||challenge.purpose!=='kernel-account-initialization'||challenge.phase!=='sign-operation-hash'||challenge.initializationReviewDigest!==operation.initializationReviewDigest||challenge.operationHash!==operation.userOperationHash)return;kernelWalletBusy=true;let signature;try{signature=await kernelWallet.signOperationHash({expectedOwner:operation.owner,chainId:46630,operationHash:challenge.operationHash,expiresAt:challenge.expiresAt});if(kernelSetupView?.flow?.walletChallenge?.id!==challenge.id)throw Error();kernelSetupView.flow.walletChallenge=await kernelWalletTransport('respond',{challengeId:challenge.id,response:{signature}});}catch{toast('Wallet approval was not confirmed. Read saved status; do not request another signature.','error');try{await readKernelStatus();}catch{}}finally{signature=undefined;kernelWalletBusy=false;renderKernelSetup();}}
}
// Wallet signatures travel once through a memory-only request, never the save/retry machinery.
let ownerWallet=null,ownerFlowView=null,ownerWalletBusy=false;
async function walletTransport(action,body){
 const response=await workspaceFetch(`/api/local/owner-flow/wallet/${action}`,{method:'POST',headers:{'content-type':'application/json'},credentials:'same-origin',cache:'no-store',body:JSON.stringify(body),signal:AbortSignal.timeout(10000)});
 const result=await response.json().catch(()=>null);
 if(!response.ok||!result?.walletChallenge)throw clientError('The wallet response was not confirmed. Read saved status; do not resend the signature.');
 return result.walletChallenge;
}
function resetOwnerWallet(){const challenge=ownerFlowView?.walletChallenge;ownerFlowView=null;if(challenge)void walletTransport('cancel',{challengeId:challenge.id}).catch(()=>{});const wallet=ownerWallet;ownerWallet=null;wallet?.close();}
function selectedTransfer(){return (state.goalTransfers||[]).find(item=>item.localReviewId===portfolioView().transferReviewId);}
function ownerFlowMarkup(record){
 if(record.imported)return '<p>Imported wallet and receipt history is read only. It cannot resume signing or submission.</p>';
 const view=ownerFlowView?.transfer?.id===record.id?ownerFlowView:null,operation=record.ownerOperation,challenge=view?.walletChallenge,live=view?.available===true&&view?.sessionAvailable===true,expired=Date.parse(record.intent.expiresAt)<=Date.now();
 const blocked=!view?'Check readiness before connecting a wallet.':!view.available?'Wallet preparation is not configured. An existing supported account, verified test token and gas coverage are required. Your saved work is available without signup.':operation&&!view.sessionAvailable?'The saved review is readable, but its wallet session ended. A restart cannot restore a signature or send again.':'';
 const selected=ownerWallet?.selected();
 return `<section aria-label="Owner wallet review"><h4>Wallet and receipt status</h4>${blocked?`<p>${esc(blocked)}</p>`:''}${button('Read saved status','owner-read','secondary small')}${!operation&&view?.available&&!record.preparationStatus&&!expired?button('Prepare wallet review','owner-prepare','secondary'):''}${operation?`<dl><dt>Owner wallet</dt><dd>${esc(operation.owner)}</dd><dt>Network</dt><dd>Robinhood Testnet</dd><dt>Maximum network cost</dt><dd>${esc(networkCost(operation.maximumGasCostWei))}</dd><dt>Review expires</dt><dd>${transferReviewTime(operation.expiresAt)}</dd></dl><p>Review the token, amount, recipient and sending account above. The wallet signs an operation hash and may show only that hash. The preparation window does not impose an onchain deadline.</p><details><summary>Gas coverage and exact operation</summary><pre>${esc(JSON.stringify({sponsorshipEvidence:operation.sponsorshipEvidence,userOperationHash:operation.userOperationHash,nonce:operation.nonce,ownerReviewDigest:operation.ownerReviewDigest,unsignedOperation:operation.userOperation},null,2))}</pre></details>${live&&!record.userOperationHash&&!expired?`${button('Find wallets','owner-discover','secondary small')}${ownerWallet?`<ul>${ownerWallet.list().map(wallet=>`<li>${button(esc(wallet.name),'owner-select','secondary small',`data-id="${esc(wallet.id)}"`)}${selected?.id===wallet.id?' · Selected':''}</li>`).join('')}</ul>`:''}${selected&&(!challenge||!selected.connected&&challenge.phase!=='signed')?button('Connect selected wallet','owner-connect','secondary'):''}${challenge?`<p>Wallet request: ${esc(challenge.phase)}. Nothing is sent automatically.</p>${challenge.phase==='sign-operation-hash'?button('Approve this operation in wallet','owner-sign','primary'):''}${challenge.phase==='signed'?button('Send the reviewed operation','owner-submit','primary'):''}${button('Cancel wallet request','owner-cancel','ghost small')}`:''}`:''}`:''}${record.submission&&!record.observationStarted&&view?.available?button('Check receipt once','owner-observe','secondary'):''}${record.observationStarted?'<p>The receipt check was started. Its read budget will not reset on restart.</p>':''}${record.verification?`<p>Saved receipt: ${esc(record.verification.recordedStatus||record.verification.status||'historical observation')}. This is historical evidence; current confirmation has not been rechecked.</p>`:''}</section>`;
}
async function readOwnerStatus(){const record=selectedTransfer();if(!record||record.imported||!portfolioLocal())return;const result=await request(`/api/local/owner-flow?transferId=${encodeURIComponent(record.id)}`);if(selectedTransfer()?.id!==record.id)return;applyState(result.state);ownerFlowView=result;updateResearchModal();}
async function ownerAction(action){
 if(!portfolioLocal()||busy||pendingRequest||syncIssue||ownerWalletBusy)return;const record=selectedTransfer();if(!record||record.imported)return;
 await task(async()=>{const body={transferId:record.id,transferDigest:record.digest,...(['begin-wallet','submit'].includes(action)?{ownerReviewDigest:record.ownerOperation?.ownerReviewDigest}:{})};const result=await request(`/api/local/owner-flow/${action}`,body,'POST',{validateResult:validateGoalTransferSave});finishGoalTransferSave(result);ownerFlowView=result.ownerFlow;updateResearchModal();});
}
async function ownerUI(action,id){try{await ownerUIAction(action,id);}catch{toast('This wallet action could not be completed. Read saved status before continuing.','error');}}
async function ownerUIAction(action,id){
 if(!portfolioLocal()||busy||pendingRequest||syncIssue||ownerWalletBusy)return;
 if(action==='read'){await task(readOwnerStatus);return;}
 if(['prepare','submit','observe'].includes(action)){await ownerAction(action);return;}
 if(action==='cancel'){resetOwnerWallet();updateResearchModal();return;}
 if(!ownerFlowView?.available||!ownerFlowView?.sessionAvailable)return;
 if(action==='discover'){
  if(!ownerWallet)ownerWallet=createWalletProviderSelection({onInvalidated:reason=>{if(reason==='connecting'||reason==='closed'||reason==='selection-changed'&&(!ownerWallet?.selected()||!ownerFlowView?.walletChallenge))return;const challenge=ownerFlowView?.walletChallenge;if(challenge)void walletTransport('cancel',{challengeId:challenge.id}).catch(()=>{});ownerFlowView=null;toast('Wallet or network changed. Read saved status and review again.','error');updateResearchModal();}});
  ownerWallet.discover();updateResearchModal();return;
 }
 if(action==='select'){ownerWallet?.select(id);updateResearchModal();return;}
 const record=selectedTransfer(),operation=record?.ownerOperation;if(!operation||!ownerWallet)return;
 if(action==='connect'){
  ownerWalletBusy=true;try{await ownerWallet.connect({expectedOwner:operation.owner,chainId:46630});}catch{toast('Connect the reviewed owner account on Robinhood Testnet.','error');return;}finally{ownerWalletBusy=false;}
  if(!ownerFlowView?.walletChallenge)await ownerAction('begin-wallet');const challenge=ownerFlowView?.walletChallenge;
  if(challenge?.phase==='check-wallet'){try{ownerFlowView.walletChallenge=await walletTransport('respond',{challengeId:challenge.id,response:{account:operation.owner,chainId:46630}});}catch{await task(readOwnerStatus);}}
  updateResearchModal();return;
 }
 if(action==='sign'){
  const challenge=ownerFlowView?.walletChallenge;if(!challenge||challenge.phase!=='sign-operation-hash'||challenge.operationHash!==operation.userOperationHash||challenge.ownerReviewDigest!==operation.ownerReviewDigest)return;
  ownerWalletBusy=true;let signature;
  try{signature=await ownerWallet.signOperationHash({expectedOwner:operation.owner,chainId:46630,operationHash:challenge.operationHash,expiresAt:challenge.expiresAt});const current=ownerFlowView?.walletChallenge;if(current?.id!==challenge.id)throw Error('Wallet changed');ownerFlowView.walletChallenge=await walletTransport('respond',{challengeId:challenge.id,response:{signature}});}
  catch{toast('Wallet approval was not confirmed. Read saved status before continuing.','error');try{await readOwnerStatus();}catch{/* No signature retry. */}}
  finally{signature=undefined;ownerWalletBusy=false;updateResearchModal();}
 }
}
function openGoalTransfer(reviewId){resetOwnerWallet();const review=(state.submissionReviews||[]).find(item=>item.id===reviewId);if(!portfolioLocal()||!review||review.localWorkId!==portfolioView().selected?.work.id)return;portfolioView().transferReviewId=reviewId;updateResearchModal();}
function validateGoalTransferSave(result,intentDigest=null){const record=result.state?.goalTransfers?.find(item=>item.id===result.transferId);if(!record||record.digest!==result.transferDigest||record.financialAuthority!==false||intentDigest&&record.intent.intentDigest!==intentDigest)throw clientError('The transfer save was not confirmed. Keep the original request and do not send a replacement.');return record;}
function finishGoalTransferSave(result){const record=validateGoalTransferSave(result);applyState(result.state);if(researchView?.portfolio){portfolioView().transferReviewId=record.localReviewId;updateResearchModal();}render();}
async function prepareGoalTransfer(reviewId){if(!portfolioLocal()||busy||pendingRequest||syncIssue)return;const review=(state.submissionReviews||[]).find(item=>item.id===reviewId);if(!review||review.localWorkId!==portfolioView().selected?.work.id)return;await task(async()=>{const result=await request('/api/local/goal-transfers',{reviewId:review.id,reviewDigest:review.digest},'POST',{beforeSend:()=>portfolioLocal()&&portfolioView().selected?.work.id===review.localWorkId,validateResult:validateGoalTransferSave});if(result){finishGoalTransferSave(result);toast('Unsigned transfer retained. Nothing was signed or sent.');}});}
async function reportGoalTransfer(type,data){if(!portfolioLocal()||busy||pendingRequest||syncIssue)return;const reviewId=portfolioView().transferReviewId,record=(state.goalTransfers||[]).find(item=>item.localReviewId===reviewId);if(!record||record.imported)return;const evidence=type==='outcome-uncertain'?{}:{userOperationHash:String(data.get('gt-userop')||'').trim().toLowerCase(),transactionHash:String(data.get('gt-transaction')||'').trim().toLowerCase()||null};await task(async()=>{const result=await request('/api/local/goal-transfers/report',{transferId:record.id,transferDigest:record.digest,type,evidence},'POST',{validateResult:result=>validateGoalTransferSave(result,record.intent.intentDigest)});if(result){finishGoalTransferSave(result);toast('Reference retained. The result is still unverified.');}});}
function validateSubmissionReviewSave(result,workDigest){const record=result.state?.submissionReviews?.find(item=>item.id===result.reviewId);if(!record||record.digest!==result.reviewDigest||record.origin.workDigest!==workDigest||record.financialAuthority!==false)throw clientError('This review save could not be confirmed. Keep the original request for recovery.');return record;}
function finishSubmissionReviewSave(result){const workDigest=researchView?.portfolio?.selected?.work.digest;validateSubmissionReviewSave(result,workDigest||result.state.submissionReviews.find(item=>item.id===result.reviewId)?.origin.workDigest);applyState(result.state);if(researchView?.portfolio){Object.assign(portfolioView(),{reviewPreview:null,reviewForm:false,transferForm:null,dirty:false});updateResearchModal();}render();}
async function saveSubmissionReviewIntent(choice){const view=portfolioView(),work=view.selected?.work;if(!work||!portfolioLocal()||busy||pendingRequest||syncIssue)return;let transferDetails=null;if(choice!=='decline'){if(!view.reviewPreview)return;const {displayAmount,...details}=view.reviewPreview;transferDetails=details;}await task(async()=>{const result=await request('/api/local/submission-reviews',{workId:work.id,workDigest:work.digest,decisionDigest:work.decision.decisionDigest,choice,transferDetails},'POST',{beforeSend:()=>portfolioLocal()&&portfolioView()===view&&view.selected?.work.digest===work.digest,validateResult:result=>validateSubmissionReviewSave(result,work.digest)});if(result){finishSubmissionReviewSave(result);toast(choice==='decline'?'Decision saved. Existing transfers are unchanged.':'Review saved. Wallet approval is still required.');}});}
function capturePortfolioForm(data){const view=portfolioView();if(!view.draft)return;if(view.mode==='json')view.json=String(data.get('portfolio-json')??view.json);else{const d=view.draft;for(const key of ['currency','cash','committed','reserve','spendCap','fee','cashTargetPct','maxSnapshotAgeHours','maxSourceAgeHours'])if(data.get('pf-'+key)!==null)d[key]=String(data.get('pf-'+key));if(data.get('pf-snapshotAt')!==null)d.snapshotAt=portfolioISO(String(data.get('pf-snapshotAt')));for(const key of Object.keys(d.source))if(data.get('pf-source-'+key)!==null)d.source[key]=['publishedAt','observedAt'].includes(key)?portfolioISO(String(data.get('pf-source-'+key))):String(data.get('pf-source-'+key));for(const key of Object.keys(d.assessment))if(data.get('pf-assessment-'+key)!==null)d.assessment[key]=String(data.get('pf-assessment-'+key));for(const [index,row] of d.positions.entries()){for(const key of ['kind','exchange','ticker','network','contractAddress','issuer','underlyingListedId','assetId','value','targetPct','relation'])if(data.get(`pf-${index}-${key}`)!==null)row[key]=String(data.get(`pf-${index}-${key}`));if(data.get(`pf-${index}-assetChoice`)!==null){row.assetChoice=String(data.get(`pf-${index}-assetChoice`));if(row.assetChoice==='native')row.assetId='native';else if(row.assetId==='native')row.assetId='';}row.focus=data.get(`pf-${index}-focus`)==='on';}for(const key of ['installments','cadence'])if(data.get('pf-dca-'+key)!==null)d.dca[key]=String(data.get('pf-dca-'+key));}view.dirty=true;view.preview=null;view.error=null;}
async function portfolioRead(path,body){if(!portfolioAvailable())throw clientError('Reconnect to open your saved portfolio proposals.');const response=await workspaceFetch(portfolioPath(path),{method:body===undefined?'GET':'POST',headers:body===undefined?{}:{'content-type':'application/json'},credentials:'same-origin',cache:'no-store',redirect:'error',signal:AbortSignal.timeout(12000),...(body===undefined?{}:{body:JSON.stringify(body)})});const data=await readAgentAccessJSON(response,131072);if(!response.ok)throw clientError(data.error?.message||'The portfolio check could not be completed.');if((hosted()?(data.requestIdentity?.userId!==connection.userId||data.capabilityTruth?.localOnly!==false||data.capabilityTruth?.hosted!==true||data.capabilityTruth?.browserOnly!==true):data.capabilityTruth?.localOnly!==true)||data.capabilityTruth?.financialAuthority!==false||data.capabilityTruth?.providerCalls!==false||data.capabilityTruth?.modelCalls!==false||!/^"(?:0|[1-9]\d*)"$/.test(response.headers.get('etag')||''))throw clientError('This portfolio reply could not be confirmed.');return {data,etag:response.headers.get('etag')};}
async function portfolioAction(operation){if(!portfolioAvailable()||!researchView||researchView.loading||busy||pendingRequest||syncIssue)return;const view=researchView,owner=connection.userId;view.loading=true;portfolioView().error=null;updateResearchModal();try{await operation(()=>researchView===view&&connection.userId===owner&&portfolioAvailable()&&researchModalOpen);}catch(error){if(researchView===view)portfolioView().error=error.message;}finally{if(researchView===view){view.loading=false;updateResearchModal();}}}
function openPortfolio(){if(!portfolioAvailable())return;if(researchView.importDirty){researchView.briefError='Save or discard the research brief before opening a portfolio check.';researchView.panel='import';updateResearchModal();return;}researchView.panel='portfolio';updateResearchModal();if(!portfolioView().draft&&!portfolioView().selected)void loadPortfolio();}
async function loadPortfolio(id=null){if(portfolioView().dirty){portfolioView().error='Save or discard this draft before opening other work.';updateResearchModal();return;}await portfolioAction(async current=>{const result=await portfolioRead('/api/local/portfolio-work'+(id?'/'+encodeURIComponent(id):''));if(!current())return;if(id){if(result.data.work?.id!==id||!['angbao-local-portfolio-work@1','angbao-local-portfolio-work@2'].includes(result.data.work.format))throw clientError('A different portfolio proposal was returned.');portfolioView().selected=result.data;portfolioView().archivePanel=false;}else{portfolioView().works=result.data.works;portfolioView().selected=null;portfolioView().archivePanel=false;} });}
function manualPortfolio(){if(portfolioView().dirty)return;Object.assign(portfolioView(),{draft:portfolioBlank(),preview:null,dirty:false,mode:'guided',previousWorkId:null,selected:null,error:null});updateResearchModal();}
async function samplePortfolio(){if(portfolioView().dirty)return;await portfolioAction(async current=>{const result=await portfolioRead('/api/local/portfolio-work/sample');if(!current())return;Object.assign(portfolioView(),{draft:result.data.draft,preview:null,dirty:false,mode:'guided',previousWorkId:null,selected:null,error:null});});}
async function previewPortfolioForm(data){capturePortfolioForm(data);await portfolioAction(async current=>{const view=portfolioView();let input;if(view.mode==='json'){try{input=JSON.parse(view.json);}catch{throw clientError('The portfolio JSON is incomplete. Your draft is still here.');}}else{if(view.draft.mode==='manual')view.draft.asOf=new Date().toISOString();input=(await portfolioRead('/api/local/portfolio-work/compose',view.draft)).data.input;}if(!current())return;const result=await portfolioRead('/api/local/portfolio-work/preview',{input,...(view.previousWorkId?{previousWorkId:view.previousWorkId}:{})});if(!current())return;if(result.etag!==workspaceETag)throw clientError('The saved workspace changed. Keep your draft and refresh before saving.');view.preview={decision:result.data.decision,previousWorkId:view.previousWorkId,etag:result.etag};});}
function validatePortfolioSave(result,expectedDecisionDigest=null,expectedResearchDigest=null){const work=result.state?.portfolioWorks?.find(item=>item.id===result.workId);if(!portfolioAvailable()||!work||!['angbao-local-portfolio-work@1','angbao-local-portfolio-work@2'].includes(work.format)||work.digest!==result.workDigest||expectedDecisionDigest&&work.decision.decisionDigest!==expectedDecisionDigest||work.decision.truth?.financialAuthority!==false||expectedResearchDigest&&work.researchHandoff?.digest!==expectedResearchDigest)throw clientError('The saved portfolio proposal could not be confirmed. Keep the original request for recovery.');return work;}
function portfolioSavedComparison(work,savedState){if(!work.previousWorkRef)return {status:'first-proposal',changes:[],amounts:null};const previous=savedState.portfolioWorks.find(item=>item.id===work.previousWorkRef.id);if(!previous)return {status:'baseline-unavailable',changes:[],amounts:null};const changes=[];for(const [key,label] of [['sources','Supplied sources'],['assessment','Agent assessment'],['portfolio','Portfolio values'],['policy','Allocation targets and limits']])if(portfolioCanonicalUI(previous.decision.snapshots[key])!==portfolioCanonicalUI(work.decision.snapshots[key]))changes.push({key,label});const before=previous.decision.plan,after=work.decision.plan;return {status:before&&after?'comparable':'inputs-require-review',baselineId:previous.id,changes,amounts:before&&after&&before.currency===after.currency&&before.minorUnitExponent===after.minorUnitExponent?{currency:after.currency,minorUnitExponent:after.minorUnitExponent,before:before.investmentMinor,after:after.investmentMinor,change:after.investmentMinor-before.investmentMinor}:null};}
function finishPortfolioSave(result){const work=validatePortfolioSave(result);applyState(result.state);if(researchView){Object.assign(portfolioView(),{draft:null,researchDraft:null,researchText:'',preview:null,dirty:false,selected:{work,comparison:result.comparison||portfolioSavedComparison(work,result.state)},error:null});researchView.panel='portfolio';updateResearchModal();}render();toast('Proposal saved. No money moved and no approval was granted.');}
async function savePortfolio(){const view=portfolioView(),preview=view.preview;if(!portfolioAvailable()||!preview||preview.etag!==workspaceETag||researchView.loading||pendingRequest||syncIssue)return;const owner=connection.userId,currentView=researchView;await task(async()=>{const result=await request(preview.handoff?'/api/local/research-portfolio':portfolioPath(),{...(preview.handoff?{handoff:preview.handoff}:{decision:preview.decision}),...(preview.previousWorkId?{previousWorkId:preview.previousWorkId}:{})},'POST',{beforeSend:()=>researchView===currentView&&portfolioView().preview===preview&&portfolioAvailable(),isCurrent:()=>connection.userId===owner&&portfolioAvailable(),validateResult:result=>validatePortfolioSave(result,preview.decision.decisionDigest,preview.handoff?.digest)});if(result)finishPortfolioSave(result);});}
function editPortfolio(){portfolioView().preview=null;updateResearchModal();}
function discardPortfolio(){Object.assign(portfolioView(),{draft:null,researchDraft:null,researchText:'',preview:null,dirty:false,selected:null,error:null,mode:'guided',json:'',previousWorkId:null,reviewForm:false,reviewPreview:null,transferForm:null});updateResearchModal();void loadPortfolio();}
function addPortfolioPosition(){const view=portfolioView();if(!view.draft||view.draft.positions.length>=8)return;const used=new Set(view.draft.positions.map(row=>row.id));let index=1;while(used.has('asset-'+index))index++;view.draft.positions.push({id:'asset-'+index,kind:'listed-equity',exchange:'',ticker:'',value:'',targetPct:'',focus:false,relation:'context-only'});view.dirty=true;view.preview=null;updateResearchModal();}
function removePortfolioPosition(index){const view=portfolioView();if(!view.draft||!Number.isInteger(index)||index<0||index>=view.draft.positions.length)return;view.draft.positions.splice(index,1);view.dirty=true;view.preview=null;updateResearchModal();}
