function portfolioGuided(){const view=portfolioView();try{if(!view.guidedInput||portfolioCanonicalUI(JSON.parse(view.json))!==portfolioCanonicalUI(view.guidedInput))throw Error();view.mode='guided';view.preview=null;view.dirty=true;view.error=null;}catch{view.error='This JSON carries changes the simple form cannot preserve. Continue in JSON, or discard the draft before starting a new form.';}updateResearchModal();}
