 await verifyIdentity();if(!current())return null;
 const response=await workspaceFetch('/api/research/methods/preview',{method:'POST',headers:{'content-type':'application/json',...(hosted()?{'X-Workspace-User':owner}:{})},credentials:'same-origin',cache:'no-store',redirect:'error',signal:AbortSignal.timeout(12000),body:JSON.stringify({workId,brief})});
