function contextPayload(data, selectedGoalId) {
  const mode=String(data.get('inputMode')||'');
  if (!['sample','manual'].includes(mode)) throw new Error('Choose Sample or My inputs.');
  const name=String(data.get('goalName')||'').trim(),currency=String(data.get('currency')||'').trim().toUpperCase();
  if (!name||name.length>80) throw new Error('Enter a goal name using 1–80 characters.');
  if (!/^[A-Z]{3}$/.test(currency)) throw new Error('Enter a three-letter currency code.');
  try { formatMoney(0,currency); } catch { throw new Error('Enter a supported three-letter currency code, such as SGD.'); }
  const targetAmount=amount(data,'targetAmount');
  if (targetAmount<=0) throw new Error('Enter a target amount greater than zero.');
  if (mode===inputMode()&&state.goals.length>1&&currency!==state.cash.currency) throw new Error('Other saved goals use this currency. Keep it unchanged.');
  const selected=selectedGoalId?state.goals.find(goal=>goal.id===selectedGoalId):state.goals[0];
  if(!selected)throw new Error('This goal is no longer saved. Start a new review.');
  if(selectedGoalId&&mode!==inputMode())throw new Error('Keep the current input mode when repeating a review.');
  const goal={id:mode!==inputMode()?(mode==='sample'?'emergency-fund':crypto.randomUUID()):selected.id,name,currency,targetAmount,currentAmount:amount(data,'currentAmount'),monthlyContribution:amount(data,'monthlyContribution')};
  return {inputMode:mode,cash:{available:amount(data,'available'),upcomingBills:amount(data,'upcomingBills'),monthlyIncome:amount(data,'monthlyIncome'),monthlyExpenses:amount(data,'monthlyExpenses'),currency},goals:mode===inputMode()?state.goals.map(item=>item.id===goal.id?goal:item):[goal],rules:{reserve:amount(data,'reserve'),maxSuggestion:amount(data,'maxSuggestion')}};
}
async function saveContext(data) {
  const payload=contextPayload(data);
  if (payload.inputMode==='manual'&&!api) throw new Error('Start Angbao on this device or sign in to save your own inputs.');
  state={...state,...payload};
  if (api) applyState(await request('/api/state',payload,'PUT'));
  else saveLocal();
  clearContextEdits(); render(); toast('Context saved.');
}
