const agentScopeLabels={'workspace:read':'Read saved context','history:read':'Read review history','reviews:create':'Run reviews','feedback:write':'Save review feedback','research:read':'Read saved briefs','research:write':'Save briefs'};
const agentGrantUUID=/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
