function clearAgentAccess(){agentAccessSerial++;agentAccessView=null;agentToken=null;agentAccessModalOpen=false;}
function agentAccessCurrent(view,serial){if(agentAccessView===view&&connection.userId!==view.ownerId){closeModal();return false;}return agentAccessModalOpen&&agentAccessView===view&&agentAccessSerial===serial&&connection.status==='ready'&&connection.userId===view.ownerId&&hosted();}
