function agentGrantFormDefaults(){return {name:'',scopes:['workspace:read'],expiresInHours:'24',maxReviewRuns:'20',maxRequests:'100',dataAccessConsent:false,reviewOnlyConsent:false,researchMemoryConsent:false};}
