let localClaimView=null,localClaimSerial=0;
function clearLocalClaim(){localClaimSerial++;localClaimView=null;}
function claimCurrent(view,serial){return localClaimView===view&&localClaimSerial===serial&&connection.status==='ready'&&hosted()&&connection.userId===view.ownerId;}
