async function recoverLocalClaim(){const view=localClaimView,serial=localClaimSerial;if(!view?.alreadyClaimed||!view.preview||view.loading||!claimCurrent(view,serial))return;view.loading=true;view.error=null;updateLocalClaim();try{const readback=await claimRequest(view,serial,`/api/local-claims/${view.preview.claimId}`);if(!readback||!claimCurrent(view,serial))return;validateClaimReadback(readback.data,view);applyState(readback.data.state);workspaceETag=readback.etag;view.completed=true;render();}catch(error){if(claimCurrent(view,serial))view.error=error.message;}finally{if(claimCurrent(view,serial)){view.loading=false;updateLocalClaim();}}}
document.addEventListener('change',event=>{if(event.target.matches?.('[data-local-claim-file]')){void selectLocalClaimFile(event.target.files?.[0]);return;}const view=localClaimView;if(!view||view.loading)return;if(event.target.matches?.('[data-local-claim-policy]')&&!view.operation){view.settingsPolicy=event.target.value;view.preview=null;view.confirmed=false;updateLocalClaim();}if(event.target.matches?.('[data-local-claim-consent]')){view.confirmed=event.target.checked;updateLocalClaim();requestAnimationFrame(()=>document.querySelector('[data-local-claim-consent]')?.focus());}});

