function sampleNotice() { return `<details class="sample-notice"><summary><span class="sample-dot"></span>${inputMode()==='manual'?'My inputs · unverified':'Sample inputs'} <span class="muted">Details</span></summary><p>${inputMode()==='manual'?'These values were entered by you and remain unverified. Their source date and freshness are unknown.':'Sample financial context.'} No paid service is enabled. ${connection.directOwnerTestnet?'Savings reviews and research do not move money. Each optional testnet transfer needs separate wallet approval.':'Financial actions are off.'} No financial accounts are connected. ${hosted()?'This account workspace is separate from your local workspace.':api?'The interface and local agent commands use the same workspace.':'This browser preview saves samples in this browser.'}</p></details>`; }
function blankDraft(starterId) {
  const recipe=recipes.find(r=>r.id===starterId);
  return {id:crypto.randomUUID(),name:recipe?`${strategyName(recipe.id)} draft`:'Untitled strategy',blocks:recipe?[{id:crypto.randomUUID(),type:'strategy',config:{id:recipe.id,version:recipe.version}}]:[],status:'draft'};
}
function loadStudioDraft(id,starterId){
  const saved=(state.strategyDrafts||[]).find(d=>d.id===id);studioDraft=saved?structuredClone(saved):blankDraft(starterId);selectedBlockId=studioDraft.blocks[0]?.id||null;draftDirty=!saved;closeModal();go('studio');
}
function openStudioDraft(id,starterId){
  if(busy||syncIssue||connection.status!=='ready')return;
  if(draftDirty){pendingDraftSelection={id,starterId,ownerId:connection.userId,route:route()};openModal('Discard draft changes?','<p>Opening another draft discards this draft’s unsaved changes. Context edits are kept.</p>',button('Keep editing','close','secondary')+button('Download edits','download-edits','secondary')+button('Discard draft edits','discard-open-draft'));return;}
  loadStudioDraft(id,starterId);
}
async function confirmDraftReplacement(){
  const next=pendingDraftSelection;if(!next||busy||syncIssue||connection.status!=='ready')return;
  await task(async()=>{await verifyIdentity();if(next.ownerId!==connection.userId)throw clientError('The signed-in account changed. Reload its workspace.',{status:401});if(!syncIssue&&connection.status==='ready'&&pendingDraftSelection===next&&route()===next.route)loadStudioDraft(next.id,next.starterId);});
}
function focusDraftBlock(id){requestAnimationFrame(()=>document.querySelector(`[data-action="select-block"][data-id="${id}"]`)?.focus());}
function markDraftDirty(){draftDirty=true;const n=$('#draft-save-status');if(n){n.textContent='Unsaved';n.className='draft-status dirty';}}
function addDraftBlock(type, starterId) {
  if(busy||syncIssue)return;if(!studioDraft)studioDraft=blankDraft();if(studioDraft.blocks.length>=30){toast('A draft can contain up to 30 blocks.');return;}
  if(!Object.hasOwn(blockTypes,type))return;
  const recipe=recipes.find(r=>r.id===starterId)||recipes[0];const block={id:crypto.randomUUID(),type,config:type==='strategy'?{id:recipe.id,version:recipe.version}:{label:blockTypes[type]}};
  studioDraft.blocks.push(block);selectedBlockId=block.id;markDraftDirty();render();focusDraftBlock(block.id);toast(`${blockTypes[type]} added.`);
}
function moveDraftBlock(id,target,drop=false) {
  if(busy||syncIssue||!studioDraft)return;const from=studioDraft.blocks.findIndex(b=>b.id===id);if(from<0)return;let to=Number(target);if(!Number.isInteger(to))return;if(drop&&from<to)to--;to=Math.max(0,Math.min(studioDraft.blocks.length-1,to));if(from===to)return;const [block]=studioDraft.blocks.splice(from,1);studioDraft.blocks.splice(to,0,block);markDraftDirty();render();focusDraftBlock(block.id);toast(`${blockTypes[block.type]} moved to position ${to+1}.`);
}
function removeDraftBlock(id) {if(busy||syncIssue||!studioDraft)return;studioDraft.blocks=studioDraft.blocks.filter(b=>b.id!==id);if(selectedBlockId===id)selectedBlockId=studioDraft.blocks[0]?.id||null;markDraftDirty();render();if(selectedBlockId)focusDraftBlock(selectedBlockId);toast('Block removed.');}
function draftInspector() {
  const block=studioDraft?.blocks.find(b=>b.id===selectedBlockId);
  if(!block)return '<h2>Block details</h2><p>Select a block to edit its settings.</p><p>Blocks can be arranged in any order.</p>';
  const input=(key,label,max=120)=>field(label,key,block.config[key]||'',`maxlength="${max}" data-block-id="${esc(block.id)}" data-block-config="${key}"`);
  let content='';
  if(block.type==='strategy'){
    const manifest=strategyManifests.find(m=>m.id===block.config.id&&m.version===block.config.version);
    content=`<div class="field"><label for="block-strategy">Built-in version</label><select id="block-strategy" data-block-id="${esc(block.id)}" data-strategy-pin>${strategyManifests.map(m=>`<option value="${esc(m.id)}@${esc(m.version)}" ${m.id===block.config.id&&m.version===block.config.version?'selected':''}>${esc(strategyName(m.id))} · ${esc(m.version)}</option>`).join('')}</select></div>${Object.entries(manifest?.settingsSchema.properties||{}).map(([key,schema])=>field(({extraReserve:'Additional reserve',contributionCap:'Contribution cap',periodsPerMonth:'Periods per month'})[key]||key,key,block.config.settings?.[key]??'',`type="number" min="${schema.minimum}" max="${schema.maximum}" step="${schema.type==='integer'?'1':'.01'}" data-block-id="${esc(block.id)}" data-config-setting="${esc(key)}" placeholder="Default"`)).join('')}<p>This block uses the selected strategy version. The draft still cannot run.</p>`;
  }else{
    content=input('label','Label');
    if(block.type==='agent')content+=`<div class="field"><label for="agent-harness">Personal agent</label><select id="agent-harness" data-block-id="${esc(block.id)}" data-block-config="harness"><option value="">Choose an agent</option>${['Grokbot','Pi','Claude Code','Other'].map(name=>`<option ${block.config.harness===name?'selected':''}>${name}</option>`).join('')}</select></div><p>This names an agent in the draft. It does not connect one.</p>`;
    if(block.type==='source')content+=input('reference','Reference',500)+'<p>Add a source label or reference. No source is retrieved.</p>';
    if(block.type==='check')content+='<p>Describe a check here. It will not run.</p>';
    if(block.type==='context')content+='<p>Describe the input you want to use.</p>';
    if(block.type==='review')content+='<p>Describe how you want to review the result.</p>';
  }
  return `<h2>${blockTypes[block.type]}</h2>${content}`;
}
function studio() {
  if(!studioDraft){studioDraft=blankDraft();draftDirty=true;}
  const palette=(type,label,starterId)=>`<button class="palette-item" draggable="true" data-drag-kind="${starterId?'starter':'palette'}" data-block-type="${type}" ${starterId?`data-starter-id="${starterId}"`:''} data-action="${starterId?'add-starter':'add-block'}" data-id="${starterId||type}" aria-label="Add ${esc(label)}">${label}<span class="plus" aria-hidden="true">+</span></button>`;
  const blocks=studioDraft.blocks;
  return header('Strategy draft','Save your arrangement here. Run installed strategies from Strategies.',`<span id="draft-save-status" class="draft-status ${draftDirty?'dirty':''}">${draftDirty?'Unsaved':'Saved'}</span>${button('Save draft','save-draft')}`)+`<div class="studio-layout"><aside class="block-palette" aria-label="Block palette"><div class="palette-section"><h2>Blocks</h2>${['agent','source','context','check','review'].map(type=>palette(type,blockTypes[type])).join('')}</div><div class="palette-section"><h2>Strategies</h2>${recipes.map(recipe=>palette('strategy',strategyName(recipe.id),recipe.id)).join('')}</div><p class="palette-help">Drag a block into the draft or select +.</p></aside><section class="draft-canvas" aria-label="Strategy canvas"><label class="sr-only" for="draft-name">Strategy name</label><input class="draft-name" id="draft-name" data-draft-name value="${esc(studioDraft.name)}" maxlength="120"><div class="draft-meta"><span class="status">Draft</span><span>Not runnable</span><span>·</span><span>${blocks.length} blocks</span></div>${blocks.length?`<ol class="draft-blocks" aria-label="Strategy blocks">${blocks.map((block,i)=>`<li class="drop-target" data-drop-index="${i}" aria-hidden="true"></li><li class="draft-block ${block.id===selectedBlockId?'selected':''}" draggable="true" data-drag-kind="block" data-block-id="${esc(block.id)}"><span class="block-grip" aria-hidden="true">⠿</span><div class="block-title"><button class="text-button" data-action="select-block" data-id="${esc(block.id)}" aria-controls="block-inspector" aria-pressed="${block.id===selectedBlockId}">${esc(block.type==='strategy'?strategyName(block.config.id):block.config.label)}</button><small>${blockTypes[block.type]}${block.type==='strategy'?` · v${esc(block.config.version)}`:''}</small></div><div class="block-tools">${button('↑','move-block-up','ghost small',`data-id="${esc(block.id)}" aria-label="Move ${esc(blockTypes[block.type])} up" ${i===0?'disabled':''}`)}${button('↓','move-block-down','ghost small',`data-id="${esc(block.id)}" aria-label="Move ${esc(blockTypes[block.type])} down" ${i===blocks.length-1?'disabled':''}`)}${button('×','remove-block','ghost small',`data-id="${esc(block.id)}" aria-label="Remove ${esc(blockTypes[block.type])}"`)}</div></li>`).join('')}<li class="drop-target" data-drop-index="${blocks.length}" aria-hidden="true"></li></ol>`:'<div class="canvas-empty" data-drop-index="0"><strong>Drop a block here</strong><p>Or choose a block from the list.</p></div>'}<p class="field-help">Saving keeps this draft. It does not run a strategy, agent or schedule.</p></section><aside id="block-inspector" class="draft-inspector" aria-label="Block details">${draftInspector()}</aside></div>`;
}
async function persistDrafts(drafts) {
  state.strategyDrafts=drafts;
  if(api)applyState(await request('/api/state',{strategyDrafts:drafts},'PUT'));
  saveLocal();
}
async function saveStudioDraft() {
  if(!studioDraft)return;
  const draft=structuredClone(studioDraft);draft.name=draft.name.trim();if(!draft.name||draft.name.length>120)throw new Error('Enter a draft name using 1–120 characters.');
  for(const block of draft.blocks)if(block.type!=='strategy'){block.config.label=block.config.label.trim();if(!block.config.label)throw new Error('Each block needs a label.');}
  const drafts=state.strategyDrafts||[];if(!drafts.some(d=>d.id===draft.id)&&drafts.length>=20)throw new Error('This workspace already has 20 drafts. Delete one before adding another.');draft.status='draft';draft.updatedAt=new Date().toISOString();await persistDrafts([...drafts.filter(d=>d.id!==draft.id),draft]);studioDraft=structuredClone((state.strategyDrafts||[]).find(d=>d.id===draft.id)||draft);draftDirty=false;render();toast('Draft saved.');
}
function agentSetupModal(){openModal('Set up with your agent',`<p>Keep reviews and research with the agent you already use. No Angbao account is needed.</p><ol><li>Your agent checks the computer and remembers your chosen location.</li><li>Setup continues from its last verified step if interrupted.</li><li>Preview <strong>Try a savings review</strong>, or use your own figures when Angbao is ready.</li></ol><p class="field-help">If the setup file has not arrived or the computer is asleep, your agent explains the next step. Your location, saved figures and review settings are kept.</p><p class="field-help">Sign in later only when you choose an account feature.</p><a class="quiet-link" href="/agent-setup.html" target="_blank" rel="noopener">Open setup guide ↗</a>`,button('Copy setup instructions','copy-setup','primary'));}
