function closeModal() { resetDirectWallet();resetKernelWallet();kernelSetupView=null;resetOwnerWallet(); clearAgentAccess();clearLocalClaim();editorGeneration++;if(researchModalOpen)cancelResearchRead();researchModalOpen=false;pendingEditAction=null;pendingDraftSelection=null;$('#modal-root').innerHTML='';modal=null;$('#app').inert=false;document.body.style.overflow='';const target=returnFocus;returnFocus=null;if(target?.isConnected)target.focus(); }
function firstReviewMarkup(){return `<section class="first-review-panel"><h2>${reviewJourney?'Continue your review':state.portfolioWorks?.length?'Start a savings review':'Start your first review'}</h2><p>Try a savings review with example figures, or check your own figures. No money is moved.</p><div class="actions">${button(reviewJourney?'Continue setup':'Start first review','start-review')}${!hosted()?'<span class="field-help">No account needed on this device.</span>':''}</div>${!api?'<p class="field-help">This is a browser preview. <a href="/agent-setup.html">Start Angbao on this device</a> to save inputs and reviews.</p>':''}</section>`;}
function nextReviewMarkup(){
  const seen=new Set(),latest=state.reviewRuns.filter(run=>{if(!state.goals.some(goal=>goal.id===run.goalId))return false;const key=`${run.goalId}:${run.strategy?.id}`;if(seen.has(key))return false;seen.add(key);return true;}),due=latest.find(run=>['due','overdue'].includes(reviewDueStatus(run.id,state.reviewDecisions,today()).status)),run=due||latest[0];
  if(!run)return `<section class="first-review-panel"><h2>Review your own figures</h2><p>Your sample reviews are saved in Activity. Start a review with your current figures when you are ready.</p>${button('Start a review','start-review')}</section>`;
  return `<section class="first-review-panel"><h2>${due?'Time to review':'Review your latest inputs'}</h2><p>${esc(strategyName(run.strategy?.id||'cash-buffer'))} · ${esc(shortDate(run.createdAt))}. Check what changed before running another free review.</p><div class="actions">${button('Review again','repeat-review','primary',`data-id="${esc(run.id)}"`)}${dueMarkup(run,true)}</div></section>`;
}
function dueMarkup(run,full=false){
  const due=reviewDueStatus(run.id,state.reviewDecisions,today());if(due.status==='unscheduled')return '';
  const label={due:'Due today',overdue:'Overdue',upcoming:'Next check'}[due.status];
  const latest=state.reviewRuns.find(item=>item.goalId===run.goalId&&item.strategy?.id===run.strategy?.id),historical=latest&&latest.id!==run.id;
  return `<span class="review-due ${due.status}">${historical?'Earlier review · ':''}${label} · ${esc(due.nextCheck)}${full?' · Start it yourself':''}</span>`;
}
function comparisonMarkup(run){
  const explicitId=run.repeatOfReviewId||comparisonBaselines[run.id],previous=explicitId?state.reviewRuns.find(item=>item.id===explicitId):findPreviousReview(run,state.reviewRuns);
  if(!previous)return `<section class="review-comparison"><h3>Compared with an earlier review</h3><p class="field-help">${explicitId?'The selected earlier review is no longer in retained history.':'There is no earlier retained review for this goal and strategy.'}</p></section>`;
  const comparison=compareReviews(previous,run),value=(v,change)=>v===null?'Not recorded':change.kind==='money'&&change.currency?money(v,change.currency):esc(v);
  return `<section class="review-comparison"><h3>What changed</h3><p class="field-help">${explicitId?'Compared with your selected review':'Compared with the nearest earlier review for this goal and strategy'}. ${esc(reviewDate(previous.createdAt))} · <code>${esc(previous.id)}</code></p>${comparison.status==='comparable'?`<p>Suggestion: ${money(comparison.result.before,run.currency)} → ${money(comparison.result.after,run.currency)} (${comparison.result.delta>0?'+':''}${money(comparison.result.delta,run.currency)}).${comparison.unchanged?' No saved inputs, settings or suggestion changed.':''}</p>`:`<p class="field-help">${comparison.status==='unavailable'?'A full comparison is unavailable.':'These reviews cannot be compared directly.'} ${comparison.reasons.map(esc).join(' ')}</p>`}${comparison.changes.length?`<div class="comparison-scroll"><table class="comparison-table"><thead><tr><th>Input or setting</th><th>Earlier</th><th>This review</th></tr></thead><tbody>${comparison.changes.map(change=>`<tr><th scope="row">${esc(change.label)}</th><td>${value(change.before,change)}</td><td>${value(change.after,change)}</td></tr>`).join('')}</tbody></table></div>`:''}<p class="field-help">Saved values only. A change in the suggestion does not show that money moved.</p></section>`;
}
