function journeyContextForm(view){const v=key=>view.fields[key]??'';return `<input type="hidden" name="inputMode" value="${esc(view.mode)}"><p class="field-help">${view.mode==='manual'?'Enter every value, including zero where appropriate. These inputs remain unverified.':'These are sample inputs. Saving replaces your current Context; history is kept.'}</p>${field('Goal name','goalName',v('goalName'),'required maxlength="80"')}${field('Currency (three-letter code)','currency',v('currency'),`required pattern="[A-Za-z]{3}" minlength="3" maxlength="3" autocapitalize="characters" placeholder="SGD" ${state.goals.length>1&&view.mode===inputMode()?'readonly':''}`)}${state.goals.length>1&&view.mode===inputMode()?'<p class="field-help">Other saved goals use this currency, so it stays fixed. No currency conversion is performed.</p>':''}<div class="field-row">${field('Saved toward goal','currentAmount',v('currentAmount'),numeric)}${field('Goal target','targetAmount',v('targetAmount'),numeric)}</div>${field('Monthly contribution','monthlyContribution',v('monthlyContribution'),numeric)}<div class="field-row">${field('Available cash','available',v('available'),numeric)}${field('Upcoming bills','upcomingBills',v('upcomingBills'),numeric)}</div><div class="field-row">${field('Monthly income','monthlyIncome',v('monthlyIncome'),numeric)}${field('Monthly expenses','monthlyExpenses',v('monthlyExpenses'),numeric)}</div><div class="field-row">${field('Protected reserve','reserve',v('reserve'),numeric)}${field('Suggestion cap','maxSuggestion',v('maxSuggestion'),numeric)}</div><p class="field-help">All amounts use the currency above. Saving does not run a review.</p>`;}
