  openModal('Strategy settings', `<span class="tag">${esc(id)} · v${esc(version)}</span><p class="muted">These settings apply to this version. They cannot increase your cash or contribution limits.</p><form data-form="strategy-settings" data-id="${esc(id)}" data-version="${esc(version)}">${Object.entries(manifest.settingsSchema.properties).map(([key, schema]) => field(labels[key] || esc(key), key, values[key] ?? '', `type="number" min="${schema.minimum}" max="${schema.maximum}" step="${schema.type === 'integer' ? 1 : '.01'}" ${key === 'contributionCap' ? '' : 'required'}`)).join('')}<p class="muted">Periods split the monthly contribution; they do not schedule reviews. Leave the contribution limit blank to use your other limits.</p><button type="submit" class="button primary">Save strategy settings</button></form>`);
