async function saveStrategySettings(id, version, data) {
  const manifest = strategyManifests.find(item => item.id === id && item.version === version);
  if (!api || !manifest || !state.installedStrategies.some(item => item.id === id && item.version === version)) throw new Error('Install this strategy version before changing its settings.');
  const settings = {};
  for (const [key, schema] of Object.entries(manifest.settingsSchema.properties)) {
    const raw = data.get(key);
    if (raw === null || String(raw).trim() === '') { if (key !== 'contributionCap') throw new Error('Fill in the required settings.'); continue; }
    const value = Number(raw);
    if (!Number.isFinite(value) || value < schema.minimum || value > schema.maximum || (schema.type === 'integer' && !Number.isInteger(value))) throw new Error('Use settings within the displayed limits.');
    settings[key] = value;
  }
  state.installedStrategies = state.installedStrategies.map(item => item.id === id && item.version === version ? { ...item, settings } : item);
  await persist(); closeModal(); render(); toast('Strategy settings saved.');
}
