document.addEventListener('keydown',event=>{
  if(!modal)return;
  if(event.key==='Escape'){event.preventDefault();closeModal();return;}
  if(event.key!=='Tab')return;
  const dialog=$('.modal'),focusable=[...dialog.querySelectorAll('button,input,select,textarea,a[href],summary,[tabindex="0"]')].filter(element=>!element.disabled&&element.type!=='hidden'&&(!element.getClientRects||element.getClientRects().length));
  const first=focusable[0],last=focusable.at(-1);if(!first)return;
  if(!focusable.includes(document.activeElement)){event.preventDefault();(event.shiftKey?last:first).focus();}
  else if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}
  else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}
});
