// Explicit owner profile only. Opening/reloading this panel never reads the chain.
let checkpointWallet=null,checkpointSession=null,checkpointBusy=false,checkpointRows=[],checkpointMessage='',checkpointActiveAction=null;
// Original hash reports outlive reconnect/bootstrap, but never acquire another profile token.
const checkpointPendingReports=new Map();
const checkpointFreeze=value=>{if(value&&typeof value==='object'){Object.values(value).forEach(checkpointFreeze);Object.freeze(value);}return value;};
const checkpointSessionKey=session=>JSON.stringify({origin:location.origin||'',token:session.token,selection:session.selection??null,operations:session.operations});
function checkpointContext(){if(connection.mode!=='local'||connection.checkpointOwner!==true||connection.status!=='ready'||protectedViewer()||localProof()||!checkpointSession)throw Error('Reopen this owner workspace before continuing.');const session=checkpointFreeze(structuredClone(checkpointSession));return Object.freeze({generation:workspaceGeneration,session,key:checkpointSessionKey(session),origin:location.origin||''});}
const checkpointCurrent=context=>context.generation===workspaceGeneration&&connection.mode==='local'&&connection.checkpointOwner===true&&connection.status==='ready'&&!protectedViewer()&&!localProof()&&checkpointSession!==null&&checkpointSessionKey(checkpointSession)===context.key;
const checkpointReportKey=(context,id)=>context.key+'|'+id;
const checkpointPending=()=>checkpointSession?[...checkpointPendingReports.values()].filter(p=>p.context.key===checkpointSessionKey(checkpointSession)):[];
const checkpointRequire=context=>{if(!checkpointCurrent(context))throw Error('This workspace changed. Inspect the original operation before continuing.');};
async function checkpointRequest(action,body={},context=checkpointContext(),{originalReport=false}={}){
  if(originalReport){if(action!=='report')throw Error('Only the original transaction reference can use recovery.');}else checkpointRequire(context);
  const response=await fetch(context.origin+'/api/local/checkpoint-owner/'+action,{method:'POST',credentials:'omit',cache:'no-store',redirect:'error',headers:{'content-type':'application/json','X-Angbao-Checkpoint-Token':context.session.token},body:JSON.stringify(body)});
  const value=await response.json();if(!originalReport)checkpointRequire(context);if(!response.ok)throw Error(value.error?.message||'This checkpoint action stopped. Inspect the saved operation.');return value;
}
async function checkpointReport(pending){await checkpointRequest('report',pending.body,pending.context,{originalReport:true});const key=checkpointReportKey(pending.context,pending.body.id);if(checkpointPendingReports.get(key)===pending)checkpointPendingReports.delete(key);}

const checkpointKey=(o,phase)=>{const attempts=checkpointRows.find(r=>r.id===o.id)?.readAttempts||[];return o.phases.find(p=>p.phase===phase&&!attempts.some(a=>a.operationKey===p.operationKey))?.operationKey;};
function checkpointTestEth(value){const digits=String(value).padStart(19,'0');return digits.slice(0,-18)+'.'+(digits.slice(-18).replace(/0+$/,'')||'0');}
function checkpointPanel(){
  if(protectedViewer()||connection.mode!=='local'||connection.checkpointOwner!==true||connection.status!=='ready'||!checkpointSession)return;
  const retained=checkpointPending();
  openModal('Keep a public checkpoint',`<p>This separately chosen testnet action records a fingerprint of your saved proposal. It does not invest money or verify your sources. Signup is optional.</p><p role="status">${esc(checkpointMessage)}</p>${retained.map(p=>`<p>Original transaction reference awaiting acknowledgement: ${esc(p.body.transactionHash)}. Save this hash; do not resend.</p>`).join('')}${checkpointSession.operations.map((o,i)=>{
    const row=checkpointRows.find(r=>r.id===o.id),held=row?.nonceReserved,expected=row?.expected,sourceMissing=row?.selectionAvailable===false;
    const control=(label,action,disabled=false)=>`<button type="button" class="button secondary" data-checkpoint-action="${action}" data-id="${esc(o.id)}" ${checkpointBusy||disabled?'disabled':''}>${label}</button>`;
    return `<section><h3>${i===0?'1. Create your testnet checkpoint contract':'2. Record this proposal'}</h3><p>${esc(row?.status||'not-prepared')}</p>${sourceMissing?'<p>The original proposal is unavailable. You can inspect progress and save its transaction reference; new wallet reviews are stopped.</p>':''}${expected?`<dl><dt>Owner</dt><dd>${esc(expected.expectedOwner)}</dd><dt>Network</dt><dd>Robinhood Testnet</dd><dt>Contract</dt><dd>${esc(expected.contract)}</dd><dt>Maximum network fee</dt><dd>${esc(checkpointTestEth(expected.costs.maximumGasFeeWei))} test ETH</dd><dt>Native value</dt><dd>0 test ETH</dd><dt>Review expires</dt><dd>${esc(expected.expiresAt)}</dd></dl>`:''}${row?.transactionHash?`<p>Saved transaction: ${esc(row.transactionHash)}</p>`:''}${control('Prepare review','prepare',held||sourceMissing)} ${control('Refresh review','refresh-review',held||sourceMissing||!row||row.status==='not-prepared'||!checkpointKey(o,'review'))} ${control('Review in wallet','wallet',held||sourceMissing||!expected||!checkpointKey(o,'before-wallet'))} ${control('Check this receipt','observe',!row?.transactionHash||!checkpointKey(o,'observation'))} ${control('Save a transaction reference','recover-reference',!held)}${held?'<p>This operation keeps its original reservation. Do not send a replacement.</p>':''}${row?.transactionHash&&!checkpointKey(o,'observation')?'<p>This review includes no further receipt checks. Ask the owner for a new review before another check.</p>':''}${row?.readAttempts?.some(a=>!a.complete)?'<p>A previous check is incomplete. Any remaining check is a separate explicit attempt; nothing is retried automatically.</p>':''}</section>`;
  }).join('')}<p>Creating the contract and recording the proposal require two separate wallet approvals. A public fingerprint may reveal that an operation occurred; keep the private opening backup safe.</p><button type="button" class="button secondary" data-checkpoint-action="reload">Reload saved progress</button> <button type="button" class="button secondary" data-checkpoint-action="export">Download public receipt</button>`,'',true);
}
async function reloadCheckpoints(context=checkpointContext()){const value=await checkpointRequest('list',{},context);checkpointRequire(context);checkpointRows=value.operations;checkpointPanel();}
async function setupCheckpointOwner(generation=workspaceGeneration){
  const current=()=>generation===workspaceGeneration&&connection.mode==='local'&&connection.checkpointOwner===true&&connection.status==='ready'&&!protectedViewer()&&!localProof();
  if(!current())return;
  try{const response=await fetch('/api/local/checkpoint-owner/bootstrap',{headers:{'X-Angbao-Checkpoint-Bootstrap':'1'},cache:'no-store',redirect:'error'});if(!response.ok||!current())return;const session=await response.json();if(!current())return;checkpointSession=session;
    let entry=document.querySelector('#checkpoint-owner-entry');if(!entry){entry=document.createElement('button');entry.id='checkpoint-owner-entry';entry.type='button';entry.className='button secondary';entry.textContent='Open checkpoint progress';entry.addEventListener('click',()=>{void reloadCheckpoints().catch(e=>{checkpointMessage=e.message;checkpointPanel();});});document.body.append(entry);}entry.hidden=false;
  }catch{/* Ordinary/protected/hosted profiles never gain checkpoint rights. */}
}
document.addEventListener('click',event=>{
  const button=event.target.closest('[data-checkpoint-action]');if(!button||checkpointBusy||protectedViewer()||!checkpointSession)return;
  let context;try{context=checkpointContext();}catch{return;}
  const action=button.dataset.checkpointAction,o=checkpointFreeze(structuredClone(context.session.operations.find(o=>o.id===button.dataset.id)??null));
  const expected=checkpointFreeze(structuredClone(checkpointRows.find(r=>r.id===o?.id)?.expected??null));
  const keys=o?Object.freeze({review:checkpointKey(o,'review'),wallet:checkpointKey(o,'before-wallet'),observation:checkpointKey(o,'observation')}):{};
  void(async()=>{checkpointActiveAction=context;checkpointBusy=true;checkpointMessage=({prepare:'Checking your testnet account for this saved proposal…','refresh-review':'Checking the account and maximum network fee…',wallet:'Preparing the exact operation for your chosen wallet…',observe:'Checking the saved transaction once…','recover-reference':'Saving the original reference. No transaction is being sent.'})[action]||'Opening saved progress…';checkpointPanel();try{
    if(action==='reload'){await reloadCheckpoints(context);return;}
    if(action==='export'){const receipt=await checkpointRequest('public-receipt',{},context);checkpointRequire(context);download(receipt,'angbao-public-checkpoint.json');return;}
    if(!o)throw Error('Reopen the selected saved operation.');const body={purpose:o.purpose,id:o.id};
    if(action==='wallet'){
      if(!expected)throw Error('Prepare and read this review first.');checkpointRequire(context);
      const selector=checkpointWallet??=createWalletProviderSelection();selector.discover();
      const wallets=selector.list();if(wallets.length===0)throw Error('Open this page in a browser with your wallet, then reload progress.');
      const chosen=window.prompt('Choose a wallet by its number:\n'+wallets.map((w,i)=>`${i+1}. ${w.name}`).join('\n'));const index=Number(chosen)-1;if(!Number.isInteger(index)||!wallets[index])throw Error('Wallet selection cancelled. Nothing was requested.');checkpointRequire(context);selector.select(wallets[index].id);await selector.connect({expectedOwner:expected.expectedOwner,chainId:46630});checkpointRequire(context);
      const {challenge}=await checkpointRequest('begin-wallet',{...body,reviewDigest:expected.reviewDigest,operationKey:keys.wallet},context);checkpointRequire(context);
      const result=await selector[o.purpose==='angbao-commitment-create'?'sendReviewedCheckpointCreation':'sendReviewedCheckpointCommit']({challenge,expected});
      if(result.transactionHash){
        const pending=Object.freeze({context,body:checkpointFreeze({...body,challengeId:result.challengeId,transactionHash:result.transactionHash})});checkpointPendingReports.set(checkpointReportKey(context,body.id),pending);
        await checkpointReport(pending);if(checkpointCurrent(context))checkpointMessage='Transaction reference saved. Check its receipt separately.';
      }else if(checkpointCurrent(context))checkpointMessage=result.outcome==='provider-reported-rejection'?'Your wallet reported a rejection. The original reservation remains.':'The wallet outcome is unknown. Inspect wallet activity and save the original transaction reference; do not resend.';
    }else if(action==='recover-reference'){
      const pending=checkpointPendingReports.get(checkpointReportKey(context,o?.id));
      if(pending)await checkpointReport(pending);
      else{const hash=window.prompt('Paste the original transaction hash from wallet activity. This only saves a reference.');if(!hash)return;checkpointRequire(context);await checkpointRequest('recover-reference',{...body,reviewDigest:expected.reviewDigest,transactionHash:hash.trim()},context);}
      if(checkpointCurrent(context))checkpointMessage='Original reference saved. No transaction was sent.';
    }else{await checkpointRequest(action,{...body,...(['refresh-review','observe'].includes(action)?{operationKey:keys[action==='observe'?'observation':'review']}:{})},context);if(checkpointCurrent(context))checkpointMessage=action==='prepare'?'Saved preparation ready. Refresh the review before continuing.':'Saved progress updated.';}
    if(checkpointCurrent(context))await reloadCheckpoints(context);
  }catch(error){if(checkpointCurrent(context)){const pending=checkpointPendingReports.get(checkpointReportKey(context,o?.id));checkpointMessage=error.message+(pending?' Save this original hash before closing: '+pending.body.transactionHash:'');}}
  finally{if(checkpointCurrent(context)&&checkpointActiveAction===context){checkpointActiveAction=null;checkpointBusy=false;checkpointPanel();}}})();
});
